              VastuStrings.treatment : 'उपचार',
              VastuStrings.officeInverter : 'ऑफिस इनवर्टर',
              VastuStrings.officeAc : 'ऑफिस एसी',
              VastuStrings.officeStaircase : 'ऑफिस सीढ़ियाँ',
              VastuStrings.officeWatch : 'ऑफिस घड़ी',
              VastuStrings.officeElectricMeter : 'ऑफिस इलेक्ट्रिक मीटर',
              VastuStrings.home1 : 'मन का धार्मिक झुकाव. यह प्रवेश द्वार लोगों को धार्मिक, गैर-आक्रामक और शांत बनाता है। निवासी दूसरों को चोट पहुँचाने के प्रति अत्यधिक संवेदनशील हो जाता है और हमेशा दूसरों की समस्याओं को हल करने का प्रयास करता है, लेकिन इसका नकारात्मक प्रभाव उसके अपने परिवार पर पड़ता है।',
              VastuStrings.home2 : 'कट्टर व्यवहार. प्रवेश द्वार निवासियों को इस तरह से व्यवहार करने के लिए मजबूर करता है जिसे लोग आम तौर पर अस्वीकार करते हैं; लोग आमतौर पर उनकी बात सुनने से बचते हैं। निवासी हमेशा अपनी बात मनवाने की कोशिश करते हैं जिसका उनके रिश्तों पर नकारात्मक प्रभाव पड़ता है।',
              VastuStrings.home3 : 'लड़कियाँ अपनी पारिवारिक परंपराओं का उल्लंघन करती हैं। इस प्रवेश द्वार के कारण, परिवार में बड़ी हो चुकी लड़कियाँ अपने परिवार की पारंपरिक मान्यताओं और संस्कृति से परे जाने का साहस करती हैं, उदाहरण के लिए: अंतरजातीय विवाह का प्रस्ताव (भारतीय संदर्भ में)। यह प्रवेश द्वार निवासी और (उसकी वयस्क) बेटी के बीच राय, विचार और दृष्टिकोण का टकराव पैदा करता है',
              VastuStrings.home4 : 'अधिक बैंक बैलेंस. ऐसा प्रवेश द्वार अधिक बैंक बैलेंस देता है। निवासी अपने रिश्तों को एक संपत्ति की तरह महत्व देता है और उन्हें उस स्तर तक संरक्षित और पोषित करने की कोशिश करता है जहां वह आनंद को उनसे बाहर निकाल सके।',
              VastuStrings.home5 : 'आग, दुर्घटनाएं और नुकसान. यह प्रवेश द्वार आग, दुर्घटना और अप्रत्याशित हानि का कारण बनता है। लोग छोटी-छोटी बातों पर चिंतित हो जाते हैं और अपने रिश्ते खराब कर लेते हैं।',
              VastuStrings.home6 : 'अधिक लड़कियाँ पैदा होना, फिजूलखर्ची। ऐसे घरों में जन्म लेने वाली लड़कियों की संख्या अपेक्षाकृत अधिक होती है और फिजूलखर्ची भी बहुत होती है। गर्भवती माँ के लिए, इससे बच्चियों के जन्म की संभावना बढ़ जाएगी। मौज-मस्ती, साझेदारों या दोस्तों पर ख़र्च में वृद्धि।',
              VastuStrings.home7 : 'पैसा, मुनाफ़ा और सफलता. एक बहुत ही शुभ प्रवेश क्षेत्र, यह धन, लाभ और सफलता लाता है। सामाजिक जुड़ाव और संपर्क धन और समृद्धि लाते हैं।',
              VastuStrings.home8 : 'प्रभावशाली लोगों से धन लाभ होगा। यह प्रवेश द्वार निवासियों को सरकार के महत्वपूर्ण लोगों या सत्ता में बैठे लोगों के करीब लाता है। अच्छे व्यक्तिगत लाभ प्राप्त करना। सरकार में शक्तिशाली लोगों के साथ संबंधों को सुगम बनाया जाता है।',
              VastuStrings.home9 : 'छोटा स्वभाव, आक्रामक व्यवहार। यह प्रवेश द्वार लोगों को अत्यधिक क्रोधी बना देता है, कभी-कभी तो पागलपन की हद तक पहुँच जाता है। अत्यधिक क्रोध के कारण जातक को सरकार से समस्याओं का सामना करना पड़ता है।',
              VastuStrings.home10 : 'प्रतिबद्धता विफलता, अविश्वसनीयता. यह प्रवेश द्वार लोगों के लिए अपनी बात रखना कठिन बना देता है, जिससे वे अविश्वसनीय प्रतीत होते हैं। निवासी अपनी प्रतिबद्धताओं को निभाने में विफल रहते हैं, जिससे रिश्तों में समस्याएं पैदा होती हैं।',
              VastuStrings.home11 : 'असंवेदनशील व्यवहार. ऐसे घरों में लोग दूसरों की समस्याओं के प्रति असंवेदनशील हो जाते हैं। निवासी अपने परिवार के सदस्यों की अपेक्षाओं की तुलना में पैसे को अधिक महत्व देते हैं।',
              VastuStrings.home12 : 'दुर्घटनाएँ, आर्थिक हानि, चोरी। इस प्रवेश द्वार के परिणामस्वरूप दुर्घटनाएं, वित्तीय नुकसान, चोरी और ऐसी अन्य समस्याएं होती हैं। नौकर धोखा देते हैं या चोरी करते हैं और घर के निवासी उन्हें आसानी से पकड़ नहीं पाते हैं।',
              VastuStrings.home13 : 'पुत्र पर नकारात्मक प्रभाव पड़ता है। घर के बच्चों (लड़कों) पर नकारात्मक प्रभाव उत्पन्न करता है। उनके विचार और कार्य उनके माता-पिता उनसे जो अपेक्षा करते हैं उससे बिल्कुल भिन्न होते हैं। बेटा अत्यधिक पैसा खर्च करता है या ऐसा व्यवहार करता है जिससे परिवार के भीतर रिश्ते खराब होते हैं, लेकिन बाहरी दुनिया के साथ रिश्ते अच्छे हो जाते हैं।',
              VastuStrings.home14 : 'नौकरी में उन्नति. यह प्रवेश द्वार दूसरों के लिए काम करने की प्रवृत्ति को बढ़ाता है। यह एमएनसी या ऐसे अन्य उद्यमों में काम करने वाले लोगों के लिए अच्छा है। निवासी अपने नौकरों और अन्य निचले वर्ग के कर्मचारियों की अच्छी देखभाल करते हैं और उन्हें अपना काम करते रहने देते हैं।',
              VastuStrings.home15 : 'अपार समृद्धि, पैसा. यह प्रवेश द्वार अपार समृद्धि लाता है। ऐसे घर में रहने वाले लोग अपना काम निकालने में काफी होशियार हो जाते हैं। निवासी अपने कर्मचारियों के साथ स्वस्थ संबंध साझा करता है और कर्मचारी भी अपना सर्वश्रेष्ठ प्रयास करते हैं।',
              VastuStrings.home16 : 'पुत्र का जन्म, उत्पादक उत्पादन। ऐसे भूखंडों में उद्योग अत्यधिक सफल होते हैं। परिवार को अधिक पुत्रों का आशीर्वाद प्राप्त है। आम तौर पर पड़ोसियों और समाज के साथ, पड़ोसियों और समाज के साथ संबंधों में सुधार होता है, जिससे निवासियों की सामाजिक छवि ऊपर उठती है।',
              VastuStrings.home17 : 'अवरुद्ध मन, कर्ज बढ़ता जा रहा है। ऐसे घरों में रहने वाले लोग कर्ज से कम ही मुक्त हो पाते हैं, वे अपनी बुद्धि का सदुपयोग करने में खुद को असमर्थ महसूस करते हैं। यहां का निवासी हमेशा ऋण प्राप्त करने के लिए अपने संबंधों का उपयोग करने की कोशिश करता है जिसके कारण उसके रिश्तेदार उससे बचने की कोशिश करते हैं।',
              VastuStrings.home18 : 'घोर गरीबी. घोर गरीबी का द्वार. रिश्तों को बेहतर बनाने के लिए प्रयास करने और पैसा खर्च करने के बावजूद, निवासियों के रिश्ते खराब बने रहते हैं।',
              VastuStrings.home19 : 'प्रयासों का पूर्ण अपव्यय, कोई परिणाम नहीं। ऐसे घर में रहने वाले लोगों की सारी कोशिशें उनके पेशे या रिश्तों को बर्बाद होती नजर आती हैं, जिसके कारण उन्हें जीवन में असंतोष मिलता है। निवासी को अपने रिश्तेदारों की घृणा और शत्रुता का शिकार होना पड़ता है।',
              VastuStrings.home20 : 'सबसे ख़राब प्रवेश द्वारों में से एक. इससे बड़े वित्तीय नुकसान होते हैं और उन नुकसानों से उबरने में असमर्थता होती है। मकानों या अन्य संपत्तियों के बिकने की अधिक संभावना है।',
              VastuStrings.home21 : 'वास्तु के अनुसार मुख्य द्वार के लिए सबसे खराब स्थान में से एक। यह दक्षिण पश्चिम प्रवेश द्वार है जो जीवन में अस्थिरता लाता है और ख़राब वित्तीय स्थिति पैदा करता है। इसका प्रभाव निवासियों के जीवन काल पर भी पड़ सकता है।',
              VastuStrings.home22 : 'रिश्तों और करियर में अस्थिरता लाता है',
              VastuStrings.home23 : 'विशेष रूप से व्यापारियों और व्यवसायियों के लिए सर्वोत्तम संभव प्रवेश द्वारों में से एक। यह प्रवेश द्वार अद्भुत विकास और गहरी समृद्धि लाता है। बच्चों की शिक्षा के लिए या यदि आप कोई शिक्षण संस्थान खोलने की योजना बना रहे हैं तो यह भी बहुत फायदेमंद है।',
              VastuStrings.home24 : 'पुत्र का जन्म, उत्पादक उत्पादन। ऐसे भूखंडों में उद्योग अत्यधिक सफल होते हैं। परिवार को अधिक पुत्रों का आशीर्वाद प्राप्त है। पड़ोसियों और सामान्य रूप से समाज के साथ संबंधों में सुधार होता है, जिससे निवासियों की सामाजिक छवि ऊपर उठती है।',
              VastuStrings.home25 : 'वरुण सृष्टि के संचालक हैं। उनका देवतत्त्व सभी देवताओं में सर्वोच्च है। अग्नि के भाई, वह अमरता के दाता हैं। यहां का प्रवेश द्वार मिश्रित है। यह समृद्धि लाता है लेकिन लोगों को अति-महत्वाकांक्षी भी बनाता है जो कभी-कभी उनके पतन का कारण बन सकता है।',
              VastuStrings.home26 : 'दैनिक थकान और कमज़ोर शारीरिक शक्ति लाता है। कम काम करने से हमेशा थकान महसूस होती है, अवसाद होता है जिससे बीमारियाँ होती हैं।',
              VastuStrings.home27 : 'प्रयासों का पूर्ण अपव्यय, कोई परिणाम नहीं। ऐसे घर में रहने वाले लोगों की सारी कोशिशें उनके पेशे या रिश्तों को बर्बाद होती नजर आती हैं, जिसके कारण उन्हें जीवन में असंतोष मिलता है। निवासी को अपने रिश्तेदारों की घृणा और शत्रुता का शिकार होना पड़ता है।',
              VastuStrings.home28 : 'इस प्रवेश द्वार से त्वचा संबंधी रोग बहुत आम हैं। इसके अलावा लोग विकास के लिए गैरकानूनी तरीकों का इस्तेमाल करते हैं जो उन्हें गंभीर संकट में डाल सकता है',
              VastuStrings.home29 : 'हत्या की आशंका बढ़ी. ऐसे घर में रहने वालों को दूसरे लोगों की बुरी नियत से नुकसान होता है। निवासी केवल समर्थन की वस्तु बन जाता है - उसकी भावनाओं का सम्मान नहीं किया जाता है।',
              VastuStrings.home30 : 'शत्रुता, ईर्ष्या. ऐसे घरों में रहने वाले लोगों को दुश्मनों का डर सताता रहता है, जो पूरी तरह से निराधार नहीं है। निवासियों को लगता है कि दूसरे लोग उनसे ईर्ष्या करते हैं। पति-पत्नी के बीच घनिष्ठ संबंधों में संतुष्टि की कमी के कारण एक-दूसरे के प्रति असंतोष पैदा होता है। दंपत्ति उस आनंद को घर से बाहर तलाशते हैं।',
              VastuStrings.home31 : 'ढेर सारा पैसा, अधिक पुरुष संतान। यह दरवाज़ा इस पर कब्ज़ा करने वालों के लिए बहुत सारा पैसा और अधिक पुरुष संतान लाता है। यह प्रवेश द्वार नए रिश्तेदारों को आकर्षित करता है, लोग अपना लाभ समझकर ऐसे घरों के निवासियों से जुड़ना चाहते हैं।',
              VastuStrings.home32 : 'विरासत में मिले और अर्जित धन की प्रचुरता। यह प्रवेश द्वार विरासत में मिली और/या अर्जित धन की प्रचुरता सुनिश्चित करता है। यह प्रवेश द्वार जातक के अपने परिवार के साथ संबंधों को मजबूत बनाता है और इसके कारण उसे विरासत में धन प्राप्त होता है।',
              VastuStrings.kitchen1 : 'डॉक्टरों और दवाइयों पर अत्यधिक पैसा खर्च करने लगता है। स्वास्थ्य और रोग प्रतिरोधक क्षमता पर प्रतिकूल प्रभाव पड़ता है।',
              VastuStrings.kitchen2 : 'पैसे के बारे में और इसे कहां निवेश किया जाना चाहिए, इसके बारे में गलत निर्णय लें। व्यक्ति मन की स्पष्टता खो सकता है और हमेशा भ्रमित रहता है।',
              VastuStrings.kitchen3 : 'ख़ुशी कमाने के लिए आपको अधिक खर्च करना होगा। लोगों को जीवन में मौज-मस्ती और आनंद के लिए बेताब होने का कारण बनता है।',
              VastuStrings.kitchen4 : 'आप देखते हैं कि पैसे के बल पर लोगों से जुड़ें। संबंध बनाने के लिए, प्रभाव डालने/दिखावा करने/काम करवाने के लिए पैसा खर्च किया जाता है।',
              VastuStrings.kitchen5 : 'मधुमेह और उच्च रक्तचाप जैसी बीमारियाँ हैं।',
              VastuStrings.kitchen6 : 'रसोई के लिए अच्छा है. किसी को यह देखने की ज़रूरत है कि परिवार के सदस्य पैसे/कमाने के तरीकों के बारे में बात न करते रहें।',
              VastuStrings.kitchen7 : 'रसोई के लिए आदर्श. परिवार के सदस्यों को शक्ति और आत्मविश्वास प्रदान करता है। बनाया गया भोजन स्वास्थ्यवर्धक एवं स्वादिष्ट होता है।',
              VastuStrings.kitchen8 : 'रसोई के लिए अच्छा है. यह निवासियों के लिए प्रसिद्धि और पहचान लाता है और आरामदायक जीवन प्रदान करता है',
              VastuStrings.kitchen9 : 'इस क्षेत्र में रसोई बनाने से बहुत अधिक खर्च होता है और बनाया गया भोजन भी स्वादिष्ट नहीं होता है। आमतौर पर, निवासियों का पेट ख़राब होगा।',
              VastuStrings.kitchen10 : 'घर में रहने वाले लोग एक-दूसरे के साथ स्वस्थ और प्रेमपूर्ण संबंध नहीं रख पाते हैं। एक ही समय में करियर और रिश्तों में अस्थिरता है।',
              VastuStrings.kitchen11 : 'बचत प्रभावित होती है और बच्चे लाख कोशिशों के बाद भी अच्छे अंक नहीं ला पाते। उन्हें पढ़ाई के नाम से गुस्सा आने लगता है.',
              VastuStrings.kitchen12 : 'रसोई के लिए आदर्श. परिवार के लिए धन लाभ और अच्छा स्वास्थ्य सुनिश्चित करता है। रेस्टोरेंट/होटलों के लिए फायदेमंद.',
              VastuStrings.kitchen13 : 'निवासियों को थायराइड की समस्या हो सकती है। पैसा कमाने/खर्च करने के कारण उदास हो जाता है।',
              VastuStrings.kitchen14 : 'आपको पैसे के लिए समर्थन मिल सकता है लेकिन अधिकांश समय आपको पैसे के लिए समर्थन की आवश्यकता होती है।',
              VastuStrings.kitchen15 : 'खुद को आकर्षक बनाने के लिए खुद पर पैसा खर्च करना शुरू करें। इससे पति-पत्नी के बीच घनिष्ठ संबंधों में खलल पड़ सकता है।',
              VastuStrings.kitchen16 : 'उन्नति के अवसर चूकने लगेंगे। उत्तर दिशा जल तत्व से शासित होती है और यदि यहां रसोई हो तो अग्नि और जल दोनों प्रदूषित हो जाते हैं।',
              VastuStrings.bedRoom1 : 'जिस व्यक्ति का शयनकक्ष इस क्षेत्र में होता है वह व्यक्ति कभी भी अधिक समय तक बिना काम के नहीं रह सकता। यहां तक कि एक लापरवाह और आलसी व्यक्ति भी अच्छा पैसा कमा सकता है, अगर उसका शयनकक्ष यहां हो।',
              VastuStrings.bedRoom2 : 'इस क्षेत्र में शयनकक्ष बिल्कुल वर्जित है, क्योंकि यह दिमाग को परेशान करता है और व्यक्ति को चिड़चिड़े और चिड़चिड़े बना देता है। स्मृति हानि और मनोभ्रंश जैसी समस्याएं हो सकती हैं।',
              VastuStrings.bedRoom3 : 'इस क्षेत्र में एक शयनकक्ष खुशी और खुशी लाता है।',
              VastuStrings.bedRoom4 : 'पूर्वी शयनकक्ष हमें अधिक सामाजिक बनाता है। हम सामाजिक गतिविधियों में बेझिझक हिस्सा लेते हैं लेकिन इसका असर हमारे पारिवारिक जीवन पर पड़ सकता है।',
              VastuStrings.bedRoom5 : 'इस क्षेत्र में शयनकक्ष चिंता का कारण बनता है। वे चीजों को आसानी से जाने नहीं देते और इससे पति-पत्नी के रिश्ते में भी खटास आती है।',
              VastuStrings.bedRoom6 : 'पैसे के लिए जोश देता है. व्यक्ति पैसों वाला बन सकता है. धन के प्रति उसकी लालसा भी बढ़ सकती है और व्यक्ति को गर्भपात की समस्या का भी सामना करना पड़ सकता है',
              VastuStrings.bedRoom7 : 'यहां सोने वाले व्यक्ति में जबरदस्त मानसिक और शारीरिक शक्ति विकसित होती है।',
              VastuStrings.bedRoom8 : 'बेडरूम/मास्टर बेडरूम के लिए सर्वाधिक अनुशंसित क्षेत्र, क्योंकि यह शांतिपूर्ण जीवन और शांत मन देता है।',
              VastuStrings.bedRoom9 : 'इस क्षेत्र में शयनकक्ष बिल्कुल भी अनुशंसित नहीं है क्योंकि यह व्यय और निपटान का क्षेत्र है। इसलिए हमें इस क्षेत्र में सोना बंद कर देना चाहिए।',
              VastuStrings.bedRoom10 : '60 से अधिक उम्र के लोगों के लिए अच्छा शयनकक्ष। युवा जोड़े के लिए अनुशंसित नहीं है क्योंकि यह कौशल का क्षेत्र भी है और एक साथी उम्मीद करता है कि उसका साथी सभी पहलुओं में परिपूर्ण हो। वह अपने पार्टनर से परफेक्शन चाहते हैं। इसलिए, यदि संभव हो तो इस शयनकक्ष से बचें। अन्यथा, इसे संतुलित करने का प्रयास करें।',
              VastuStrings.bedRoom11 : 'यह व्यक्ति के लिए एक उत्कृष्ट शयनकक्ष है लेकिन उन्हें नकारात्मक विषयों पर बात करने से बचना चाहिए। चूंकि यह क्षेत्र ब्रह्मांड से बहुत तेजी से जुड़ता है इसलिए नकारात्मक बातों पर चर्चा करने से बचें।',
              VastuStrings.bedRoom12 : 'यह सरस्वती माता का क्षेत्र है इसलिए बोलने से पहले सोचें और सोच-समझकर बात करें।',
              VastuStrings.bedRoom13 : 'पश्चिम लाभ और लाभ का क्षेत्र है। यह शयनकक्ष धन के साथ-साथ जीवन के हर क्षेत्र में लाभ के लिए भी अच्छा है।',
              VastuStrings.bedRoom14 : 'यह क्षेत्र कोप भवन है - जहां रहने वाला व्यक्ति हमेशा किसी न किसी पर नाराज रहता है। इस क्षेत्र में शयनकक्ष की अनुशंसा नहीं की जाती है।',
              VastuStrings.bedRoom15 : 'अच्छा शयनकक्ष और उन लोगों के लिए अत्यधिक फायदेमंद है जिन्हें ऋण या वित्तीय सहायता या सहायता की आवश्यकता है।',
              VastuStrings.bedRoom16 : 'नवविवाहित जोड़ों और 12 वर्ष से कम उम्र के बच्चों के लिए अच्छा शयनकक्ष।',
              VastuStrings.toiletSepticTank1 : 'इस क्षेत्र में शौचालय होने से रोग प्रतिरोधक क्षमता कमजोर हो जाती है और बीमारियों को ठीक होने में अधिक समय लगेगा।',
              VastuStrings.toiletSepticTank2 : 'इस क्षेत्र में शौचालय गंभीर मानसिक समस्या का कारण बनते हैं और बीमारी का खतरा होता है। व्यक्ति में बुद्धि, विचार और रचनात्मकता का अभाव होता है।',
              VastuStrings.toiletSepticTank3 : 'व्यक्ति को सुस्ती महसूस होती है और वह कभी भी तरोताजा महसूस नहीं करता है। छुट्टियों की योजनाएँ बहुत सारी समस्याओं से नहीं बनती/बनती हैं।',
              VastuStrings.toiletSepticTank4 : 'छोटे सामाजिक दायरे और किसी विशेष क्षेत्र में विकास के लिए सही कनेक्शन का कारण बनता है। राजनीति से जुड़े लोग इस क्षेत्र में शौचालय का खर्च वहन नहीं कर सकते। और लोगों को दिल से जुड़ी परेशानियां भी हो जाती हैं।',
              VastuStrings.toiletSepticTank5 : 'इस क्षेत्र में शौचालय फायदेमंद है क्योंकि यह चिंता और अधिक सोचने की क्षमता को कम करता है।',
              VastuStrings.toiletSepticTank6 : 'धन के प्रवाह/तरल नकदी प्रवाह में समस्याएँ। व्यवसाय या सामान्य जीवनयापन के लिए पर्याप्त धन नहीं। हमेशा पैसों की तंगी रहती है.',
              VastuStrings.toiletSepticTank7 : 'इस क्षेत्र में शौचालय होने से आत्मविश्वास, शारीरिक शक्ति में कमी आती है और विचार को कार्य में परिवर्तित किया जा सकता है।',
              VastuStrings.toiletSepticTank8 : 'इस क्षेत्र में शौचालय निवासियों की प्रसिद्धि और आराम में बाधा डालता है। आप लगातार प्रयास कर रहे हैं लेकिन उसके लिए आपको पहचान नहीं मिल पा रही है।',
              VastuStrings.toiletSepticTank9 : 'यह वॉशरूम के लिए सबसे अच्छा क्षेत्र है क्योंकि यह निपटान का क्षेत्र है। इस क्षेत्र में एक शौचालय आपके जीवन से फिजूलखर्ची, रिश्ते आदि को दूर कर देता है।',
              VastuStrings.toiletSepticTank10 : 'पारिवारिक रिश्तों पर बुरा असर पड़ता है। जीवन में सफलता बहुत बाद में/कभी नहीं मिलती। यह क्षेत्र पितृ से संबंधित है और इस क्षेत्र में शौचालय आपको उनके आशीर्वाद से वंचित कर सकता है।',
              VastuStrings.toiletSepticTank11 : 'इस क्षेत्र में शौचालय होने के कारण पैसे नहीं बचा पा रहे हैं। संपत्ति या आभूषण जैसी पुरानी बचत ख़त्म होने लगती है। साथ ही इससे बच्चों की पढ़ाई में भी बाधा आती है।',
              VastuStrings.toiletSepticTank12 : 'निवेश की गई मेहनत का फल नहीं मिलता। लाभदायक विकास को नष्ट कर देता है और इच्छाओं/इच्छाओं की प्राप्ति में बाधा उत्पन्न करता है। संपत्ति संबंधी मामले भी सामने आ सकते हैं।',
              VastuStrings.toiletSepticTank13 : 'इस क्षेत्र में वॉशरूम की सिफारिश की जाती है क्योंकि यह अवरुद्ध भावनाओं को मुक्त करने और उदास विचारों को दूर करने में मदद करता है।',
              VastuStrings.toiletSepticTank14 : 'इस क्षेत्र में शौचालय होने से मित्रों, परिचितों और समाज से मदद और समर्थन कम हो जाता है। साथ ही बैंक से जुड़ी समस्याओं को भी भड़काता है और बैंक बैलेंस को कम करता है।',
              VastuStrings.toiletSepticTank15 : 'इस क्षेत्र में शौचालय होने से विवाहित जोड़ों के बीच आकर्षण खत्म हो जाता है। इसके अलावा, सामान्य तौर पर लोगों को आकर्षित/प्रभावित करने में भी समस्याएं हैं।',
              VastuStrings.toiletSepticTank16 : 'इस क्षेत्र में शौचालय करियर संबंधी समस्याएं पैदा कर सकते हैं। जीवन में पैसा कमाने और आगे बढ़ने के अवसरों की संभावना कम है।',
              VastuStrings.dustbin1 : 'व्यक्ति को दवा का लाभ नहीं मिलेगा. सिफारिश नहीं की गई',
              VastuStrings.dustbin2 : 'निवासियों को नए विचारों को ग्रहण करने में कठिनाई होगी, बिल्कुल भी अनुशंसित नहीं',
              VastuStrings.dustbin3 : 'निवासियों को अपने जीवन में मौज-मस्ती और खुशियों की कमी महसूस हो सकती है। सिफारिश नहीं की गई',
              VastuStrings.dustbin4 : 'निवासी समाज के महत्व को समझने में विफल रहते हैं। वे बाहरी दुनिया के लोगों से मिलने के लिए बाहर नहीं जाना चाहते। सिफारिश नहीं की गई।',
              VastuStrings.dustbin5 : 'कूड़ेदान रखने के लिए अच्छी जगह.',
              VastuStrings.dustbin6 : 'भुगतान रोक सकते हैं. जब भी कुछ अच्छा होने वाला होता है, निवासियों को बाधाओं और समस्याओं का सामना करना पड़ता है। अनुशंसित नहीं',
              VastuStrings.dustbin7 : 'शक्ति, आत्मविश्वास और सुरक्षा की हानि, अनुशंसित नहीं',
              VastuStrings.dustbin8 : 'निवासियों को बेचैनी महसूस होती है. उन्हें अच्छी नींद नहीं आ पाती. उनकी सारी मेहनत और प्रयास बर्बाद हो जाते हैं और वे जो करते हैं उसकी उन्हें कोई सराहना नहीं मिलती। अनुशंसित नहीं',
              VastuStrings.dustbin9 : 'कूड़ेदान रखने के लिए अच्छा क्षेत्र',
              VastuStrings.dustbin10 : 'इससे परिवार के सदस्यों के बीच मतभेद पैदा हो जाते हैं और लोग अपने करीबी लोगों के साथ अपने रिश्ते को अपने जीवन के सबसे बेकार पहलुओं में से एक मानने लगते हैं (एक बड़ी बात नहीं)',
              VastuStrings.dustbin11 : 'इस जोन में कूड़ादान होने से बचत पर असर पड़ता है। इसके अलावा, बच्चों की पढ़ाई में रुचि और एकाग्रता खोने लगती है।',
              VastuStrings.dustbin12 : 'अपनी मेहनत का फल और पहचान नहीं मिलेगी।',
              VastuStrings.dustbin13 : 'कूड़ेदान रखने के लिए आदर्श स्थान',
              VastuStrings.dustbin14 : 'निवासियों को समय या आवश्यकता के समय समय पर सहायता नहीं मिलेगी या उनकी बैंकिंग में बाधा आ सकती है। सिफारिश नहीं की गई',
              VastuStrings.dustbin15 : 'इससे दंपत्ति के बीच आकर्षण में बाधा आती है। सिफारिश नहीं की गई',
              VastuStrings.dustbin16 : 'व्यर्थ अवसर मिलेंगे अनुशंसित नहीं',
              VastuStrings.washingMachine1 : 'इस जोन में रखी मशीनें यहां के निवासियों के स्वास्थ्य पर असर डालती हैं।',
              VastuStrings.washingMachine2 : 'यहां रखी वॉशिंग मशीन निरर्थक विश्लेषण, चिंता और सिरदर्द का कारण बनती है - दिमाग हमेशा बेकार विचारों से भरा रहता है।',
              VastuStrings.washingMachine3 : 'इस क्षेत्र में रखी वॉशिंग मशीन मनोरंजन और कायाकल्प में बाधा डाल सकती है।',
              VastuStrings.washingMachine4 : 'लोग अपनी सामाजिक स्थिति, समाज में उनकी क्या छवि है और दूसरे उनके बारे में क्या सोचते हैं, इस बारे में सोचते रहेंगे।',
              VastuStrings.washingMachine5 : 'वाशिंग मशीन के लिए आदर्श क्षेत्र।',
              VastuStrings.washingMachine6 : 'व्यक्ति हमेशा नकदी के बारे में सोचता रहेगा और अधिक पैसा कैसे कमाया जाए। इस क्षेत्र में मशीनें उनकी तरल नकदी का मंथन भी कर सकती हैं।',
              VastuStrings.washingMachine7 : 'आत्मविश्वास में कमी और स्वास्थ्य से जुड़ी समस्याओं का सामना करना पड़ सकता है',
              VastuStrings.washingMachine8 : 'निवासियों की गहरी नींद में बाधा डालता है। बिस्तर पर भी वे चीजों का विश्लेषण करते रहते हैं और चिंतित हो जाते हैं।',
              VastuStrings.washingMachine9 : 'इस क्षेत्र में वॉशिंग मशीन खराब हो जाती है और बार-बार मरम्मत की आवश्यकता होगी।',
              VastuStrings.washingMachine10 : 'पारिवारिक संबंधों पर मंथन हो सकता है और उनके बीच मतभेद हो सकते हैं।',
              VastuStrings.washingMachine11 : 'बच्चों को जो भी काम सौंपा जाएगा उसे पूरा करने में उन्हें अधिक समय लगेगा। यहां रखी मशीनें निवासियों की बचत में भी बाधा डाल सकती हैं।',
              VastuStrings.washingMachine12 : 'एक व्यक्ति लाभ के लिए बेताब हो जाएगा जो हालांकि पूरा नहीं हो पाएगा।',
              VastuStrings.washingMachine13 : 'ईएसई के बाद मशीनें रखने के लिए आदर्श स्थान',
              VastuStrings.washingMachine14 : 'समय पर सहायता में बाधा आ सकती है और बैंकिंग मुद्दे प्रभावित हो सकते हैं',
              VastuStrings.washingMachine15 : 'व्यक्ति शारीरिक संबंधों से जुड़ी बातों के बारे में सोचता रहेगा। इससे पति-पत्नी के रिश्ते भी खराब होते हैं।',
              VastuStrings.washingMachine16 : 'व्यक्ति हमेशा अपनी नौकरी बदलने के बारे में सोचता रहेगा और उसे कभी अच्छे अवसर नहीं मिलेंगे। तथा अपने करियर के बारे में सोचते रहेंगे।',
              VastuStrings.temple1 : 'यह शिव पूजन, शिव परिवार, धन्वंतरि, अश्विनी कुमार पूजन के लिए आदर्श क्षेत्र है क्योंकि यह स्वास्थ्य और प्रतिरक्षा प्रदान करेगा।',
              VastuStrings.temple2 : 'पूजा कक्ष के लिए आदर्श और निवासियों पर इसका बहुत सकारात्मक प्रभाव पड़ता है। मानसिक स्पष्टता देता है और अपने आंतरिक स्व से जुड़ता है।',
              VastuStrings.temple3 : 'इस क्षेत्र में पूजा कक्ष तरोताजा महसूस करने और ऊर्जा से भरपूर होने में मदद करता है। दैनिक तनाव से निपटना आसान लगता है।',
              VastuStrings.temple4 : 'इस क्षेत्र में पूजा कक्ष राजनेताओं और नौकरशाहों के लिए सबसे फायदेमंद है क्योंकि इससे वरिष्ठों और हाईकमान का आशीर्वाद मिलता है।',
              VastuStrings.temple5 : 'स्टॉकब्रोकरों को छोड़कर यहां पूजा कक्ष की अनुशंसा नहीं की जाती है क्योंकि यह क्षेत्र बेचैनी और चिंता पैदा करता है।',
              VastuStrings.temple6 : 'मां दुर्गा की पूजा के अलावा किसी अन्य की पूजा करने की अनुशंसा नहीं की जाती है क्योंकि इससे दुर्घटनाएं हो सकती हैं और धन हानि का डर रहता है।',
              VastuStrings.temple7 : 'हनुमानजी की पूजा के अतिरिक्त अन्य कोई भी पूजा अनुशंसित नहीं है। उनकी पूजा से शक्ति, शक्ति और आत्मविश्वास मिलता है।',
              VastuStrings.temple8 : 'माँ काली पूजा के लिए, इस क्षेत्र की अनुशंसा की जाती है लेकिन अन्य पूजाएँ अप्रभावी हैं।',
              VastuStrings.temple9 : 'यहां केवल अघोरी पूजा ही की जानी चाहिए क्योंकि अन्य प्रभावी नहीं होती हैं और नुकसान पहुंचा सकती हैं।',
              VastuStrings.temple10 : 'इस क्षेत्र में पितृ पूजा आदर्श है और इस क्षेत्र में विश्वकर्मा पूजा श्रमिकों को अधिक कौशल प्रदान करती है। अन्य पूजाओं की अनुशंसा नहीं की जाती है क्योंकि इससे भुगतान की वसूली धीमी हो सकती है और वित्तीय विकास में बाधा आ सकती है।',
              VastuStrings.temple11 : 'यहां ज्ञान देने वाली मां सरस्वती को छोड़कर अन्य पूजा करने से बचना चाहिए।',
              VastuStrings.temple12 : 'यहां सिख गुरुओं, जैन गुरुओं, साईं बाबाजी, भगवान बुद्ध, भगवान महावीर और यीशु जैसे सभी गुरुओं की पूजा की जानी चाहिए क्योंकि इससे प्रचुरता और वित्तीय लाभ मिलता है। अन्य सभी पूजाओं से बचना चाहिए',
              VastuStrings.temple13 : 'यक्षिणी पूजा को छोड़कर अन्य पूजा से बचना चाहिए।',
              VastuStrings.temple14 : 'यह क्षेत्र पितृ पूजा के लिए आदर्श है।',
              VastuStrings.temple15 : 'शक्ति और प्रचुर धन प्राप्ति के लिए सभी तंत्र अनुष्ठान इस क्षेत्र में किए जा सकते हैं। यहां अन्य सभी पूजाओं से बचना चाहिए।',
              VastuStrings.temple16 : 'यह क्षेत्र यक्ष साधना, लक्ष्मी और गणेश पूजन के लिए आदर्श है। इन्हें छोड़कर बाकी सभी पूजाएं निष्फल होती हैं।',
              VastuStrings.servantRoom1 : 'उत्तर-उत्तर-पूर्व (एनएनई) क्षेत्र में रहने वाले नौकर यहीं रहते हैं लेकिन अपने नियोक्ताओं के मुकाबले अपने स्वास्थ्य को प्राथमिकता देते हैं। समय के साथ, उनमें कमजोर प्रतिरक्षा विकसित हो सकती है।',
              VastuStrings.servantRoom2 : 'उत्तर पूर्व (एनई) क्षेत्र को नौकर कक्ष के लिए एक अनुकूल स्थान माना जाता है। इस क्षेत्र में रहने वाला नौकर कभी-कभी साधारण निर्देश या कार्य भी भूल सकता है, लेकिन वह वफादार और समर्पित रहता है।',
              VastuStrings.servantRoom3 : 'पूर्व-उत्तरपूर्व (ईएनई) क्षेत्र में रहने वाले नौकर मौज-मस्ती पसंद करते हैं। उन्हें टेलीविजन देखना और मनोरंजन के विभिन्न साधनों में शामिल होना अच्छा लगता है, जिसके कारण कभी-कभी डांट भी पड़ती है। हालाँकि, वे घर में खुशनुमा माहौल बनाए रखने में योगदान देते हैं।',
              VastuStrings.servantRoom4 : 'पूर्व (ईएएसटी) क्षेत्र में नौकर कक्ष होने से अक्सर नौकरों के निष्क्रिय रिश्तेदारों से नियमित मुलाकात होती रहती है, जिससे गृहस्वामी को असुविधा होती है और नौकरों का समय बर्बाद होता है। इसलिए इसे यहां न रखना ही बेहतर है।',
              VastuStrings.servantRoom5 : 'पूर्व-दक्षिणपूर्व (ईएसई) क्षेत्र में रहने वाले नौकर को चीजों की सीमित समझ हो सकती है लेकिन वह लंबे समय तक परिवार के साथ रहता है। हालाँकि, वे अक्सर अपने वादे निभाने में संघर्ष करते हैं और झूठ बोलने की प्रवृत्ति रखते हैं।',
              VastuStrings.servantRoom6 : 'दक्षिणपूर्व (एसई) क्षेत्र में रहने वाले नौकर लगातार अपने कर्तव्यों में व्यस्त रहते हैं। वे अपने द्वारा प्रदान की जाने वाली सेवाओं के प्रति अपने मुआवजे के प्रति निष्ठा और संतुष्टि की मजबूत भावना प्रदर्शित करते हैं। इसलिए, दक्षिण-पूर्व क्षेत्र नौकर कक्ष के लिए एक आदर्श स्थान है।',
              VastuStrings.servantRoom7 : 'दक्षिण-दक्षिणपूर्व (एसएसई) दिशा में एक नौकर कक्ष नौकर के लिए जल्दी और कुशलता से काम करने के लिए प्रेरणा के स्रोत के रूप में कार्य करता है। वे परिवार के सदस्यों के लिए भरोसा करने की ताकत का एक अतिरिक्त स्रोत बन जाते हैं, जिससे यह ऐसे कमरे के लिए उपयुक्त स्थान बन जाता है।',
              VastuStrings.servantRoom8 : 'दक्षिण दिशा में रहने वाले नौकर अपने प्रयासों के लिए उचित स्वीकृति और कृतज्ञता की अपेक्षा करते हैं। वे मौद्रिक पुरस्कारों से अधिक आत्म-सम्मान को प्राथमिकता देते हैं और वफादारी प्रदर्शित करते हैं। अत: यह क्षेत्र नौकर कक्ष के लिए उपयुक्त स्थान है।',
              VastuStrings.servantRoom9 : 'दक्षिण-दक्षिण-पश्चिम (एसएसडब्ल्यू) क्षेत्र में नौकर कक्ष वहां रहने वाले नौकरों के स्वास्थ्य पर प्रतिकूल प्रभाव डाल सकता है। उन्हें परिवार से जुड़ने में कठिनाई हो सकती है और वे अपर्याप्त और अनुत्पादक महसूस करने लग सकते हैं।',
              VastuStrings.servantRoom10 : 'दक्षिण-पश्चिम (एसडब्ल्यू) दिशा में एक नौकर कक्ष नौकरों के लिए स्वादिष्ट भोजन पकाने जैसे अपने कौशल को निखारने के लिए एक स्थान के रूप में कार्य करता है। वे अपने कार्यों को पूरा करने के लिए अधिक कुशल और प्रभावी तरीके खोजते हैं। जब यह क्षेत्र संतुलित होता है, तो यह नौकरों और उनके नियोक्ताओं के बीच एक मजबूत और स्थायी बंधन को बढ़ावा देता है। कुल मिलाकर, यह नौकर कक्ष के लिए एक अनुकूल स्थान है।',
              VastuStrings.servantRoom11 : 'पश्चिम-दक्षिण-पश्चिम (डब्ल्यूएसडब्ल्यू) दिशा में एक नौकर कक्ष एक बार फिर एक अनुकूल विकल्प है, क्योंकि यह नौकरों को लगातार अभ्यास के माध्यम से अपने कौशल को बढ़ाने की अनुमति देता है। वे नई चीज़ें सीखने को प्राथमिकता देंगे, जैसे नई रेसिपी आज़माना, और अपने ज्ञान के आधार का विस्तार करना।',
              VastuStrings.servantRoom12 : 'पश्चिम (पश्चिम) दिशा केवल रसोइयों के रहने के लिए आदर्श है।',
              VastuStrings.servantRoom13 : 'पश्चिम-उत्तर-पश्चिम (डब्ल्यूएनडब्ल्यू) दिशा में, नौकर अपने काम, नियोक्ता और सामान्य रूप से जीवन से संबंधित छोटे-छोटे मुद्दों पर शिकायत करते हैं और भावुक हो जाते हैं। हालाँकि, वे आम तौर पर अपनी नौकरी नहीं छोड़ते या अपनी ज़िम्मेदारियों से पीछे नहीं हटते।',
              VastuStrings.servantRoom14 : 'उत्तर-पश्चिम दिशा में रहने वाले नौकरों के मन में तरह-तरह के विचार और चिंताएँ होती हैं, लेकिन वे लगातार अपने नियोक्ताओं का समर्थन करते हैं।',
              VastuStrings.servantRoom15 : 'उत्तर-उत्तर-पश्चिम (एनएनडब्ल्यू) दिशा में रहने वाले नौकर परिवार को जल्दी छोड़ देते हैं। इसलिए, इस क्षेत्र में नौकर कक्ष रखना उचित नहीं है।',
              VastuStrings.servantRoom16 : 'उत्तर (उत्तर) क्षेत्र में, नौकर बेहतर कैरियर के अवसरों के प्रति अत्यधिक जागरूक हो जाते हैं। वे लगातार बेहतर नौकरी की संभावनाओं की तलाश करते हैं जो उच्च वेतन प्रदान करती हैं। वे अक्सर वेतन वृद्धि का अनुरोध करते हैं, और कुछ मामलों में, वे चोरी का सहारा ले सकते हैं या समय से पहले अपनी नौकरी छोड़ सकते हैं। यह स्थान अनुकूल नहीं माना जाता है.',
              VastuStrings.guestRoom1 : 'इस क्षेत्र का उपयोग अतिथि शयनकक्ष बनाने के लिए किया जा सकता है। इसका आपके जीवन पर कोई भी अच्छा या बुरा प्रभाव नहीं पड़ता है।',
              VastuStrings.guestRoom2 : 'अतिथि देवो भवः - भारतीय अपने मेहमानों को भगवान मानकर उनका बहुत आदर करते हैं। इसलिए, अतिथि शयनकक्ष बनाने के लिए पूर्वोत्तर (एनई) क्षेत्र का उपयोग किया जा सकता है।',
              VastuStrings.guestRoom3 : 'पूर्व-उत्तरपूर्व (ईएनई) क्षेत्र में अतिथि शयनकक्ष बनाया जा सकता है। यह मेहमानों को उनके प्रवास के दौरान एक ताज़ा और आनंददायक अनुभव प्रदान करेगा।',
              VastuStrings.guestRoom4 : 'पूर्वी क्षेत्र में बनाया गया अतिथि शयनकक्ष आपके मेहमानों के साथ आपके रिश्ते और जुड़ाव को बढ़ाता है।',
              VastuStrings.guestRoom5 : 'यदि आप अपने मेहमानों के बार-बार और लंबे समय तक रुकने से थक गए हैं और उन्हें दूर रखना चाहते हैं, तो पूर्व-दक्षिणपूर्व (ईएसई) क्षेत्र आपके घर में आपके मेहमानों के लिए एकदम सही जगह है। अन्यथा, अतिथि शयनकक्ष बनाने के लिए इस क्षेत्र से बचने की सलाह दी जाती है।',
              VastuStrings.guestRoom6 : 'दक्षिण-पूर्व (एसई) क्षेत्र में अतिथि शयनकक्ष बनाने से धन के प्रवाह में बाधा आ सकती है, विशेषकर वह धन जो आपने दूसरों को उधार दिया हो। इसलिए, अतिथि कक्ष के लिए इस क्षेत्र का उपयोग करने से बचने की सलाह दी जाती है।',
              VastuStrings.guestRoom7 : 'दक्षिण-दक्षिणपूर्व (एसएसई) क्षेत्र में अतिथि शयनकक्ष बनाने की अनुमति है। इस क्षेत्र में बने अतिथि कक्ष में आप अपने मेहमानों के साथ अधिक सुरक्षित और मजबूत महसूस करेंगे।',
              VastuStrings.guestRoom8 : 'दक्षिण (दक्षिण) क्षेत्र में अतिथि शयनकक्ष बनाने की अनुशंसा नहीं की जाती है। यह समाज द्वारा आपके प्रयासों की मान्यता के लिए समस्याग्रस्त साबित हो सकता है।',
              VastuStrings.guestRoom9 : 'दक्षिण-दक्षिण-पश्चिम (एसएसडब्ल्यू) क्षेत्र में अतिथि शयनकक्ष बनाने से बचें, क्योंकि यह निपटान का क्षेत्र है। ऐसा करने से मेहमानों के ठहरने के उद्देश्य की पूर्ति में बाधा आ सकती है और उनके साथ आपके रिश्ते भी ख़राब हो सकते हैं।',
              VastuStrings.guestRoom10 : 'दक्षिण-पश्चिम (एसडब्ल्यू) क्षेत्र में अतिथि शयनकक्ष बनाना एक अच्छा विकल्प है। यह क्षेत्र आपके मेहमानों के साथ आपके रिश्ते को भी बेहतर बनाता है।',
              VastuStrings.guestRoom11 : 'पश्चिम-दक्षिण-पश्चिम (WSW) क्षेत्र में अतिथि शयनकक्ष बनाया जा सकता है। यह आपके मेहमानों के साथ आपकी निकटता को बेहतर बनाता है।',
              VastuStrings.guestRoom12 : 'पश्चिमी क्षेत्र में अतिथि शयनकक्ष बनाने से बचें, क्योंकि इससे आपको अपने प्रयासों का पूरा परिणाम नहीं मिल पाएगा। आपका लाभ केवल अस्थायी रूप से प्रकट हो सकता है।',
              VastuStrings.guestRoom13 : 'आप पश्चिम-उत्तर-पश्चिम (WNW) क्षेत्र में अतिथि शयनकक्ष बना सकते हैं क्योंकि इसका कोई नकारात्मक प्रभाव नहीं पड़ता है। इसके अतिरिक्त, यह सुनिश्चित करता है कि आपके मेहमानों के मन में आपके प्रति कोई अवरुद्ध या नकारात्मक भावना न हो।',
              VastuStrings.guestRoom14 : 'उत्तर-पश्चिम (एनडब्ल्यू) क्षेत्र में अतिथि शयनकक्ष बनाने से बचें, क्योंकि इससे आपको ज़रूरत के समय सहायता और सहायता प्राप्त करने में समस्याएँ पैदा होती हैं।',
              VastuStrings.guestRoom15 : 'इस क्षेत्र में अतिथि शयनकक्ष का उपयोग केवल आपके परिवार के मेहमानों के लिए किया जा सकता है; इस कमरे में बाहरी लोगों से बचना चाहिए।',
              VastuStrings.guestRoom16 : 'जब अतिथि शयनकक्ष इस क्षेत्र में स्थित होता है, तो आपके जीवन में मेहमानों (अस्थायी) के रूप में नए अवसर आते हैं; इसलिए, इसे यहां टाला जाना चाहिए।',
              VastuStrings.bar1 : 'इस क्षेत्र में बार से बचना चाहिए, क्योंकि इससे घर के निवासियों का स्वास्थ्य खराब होता है।',
              VastuStrings.bar2 : 'यह आपके घर में बार बनाने के लिए अच्छी जगह नहीं है, क्योंकि यह मन को भटकाव और अस्थिरता देता है।',
              VastuStrings.bar3 : 'यह क्षेत्र बार बनाने के लिए बुरा या अशुभ नहीं है।',
              VastuStrings.bar4 : 'इस क्षेत्र में बनाए जाने पर बार आपके और आपके सामाजिक रिश्तों के बीच दूरी पैदा करता है। इसलिए, यह बार के लिए अच्छा स्थान नहीं है।',
              VastuStrings.bar5 : 'इस जोन को बार बनाने की अनुमति है। यह चिंता को कम करता है और घर में सौहार्दपूर्ण रिश्ते बनाता है।',
              VastuStrings.bar6 : 'इस क्षेत्र में बार नहीं बनाना चाहिए, इससे धन की हानि होती है।',
              VastuStrings.bar7 : 'यह फिर से बार के लिए अच्छी जगह नहीं है। इससे आत्मविश्वास में कमी और निःस्वार्थता की भावना उत्पन्न होती है। साथ ही इससे हीन भावना भी बढ़ती है।',
              VastuStrings.bar8 : 'जब इस क्षेत्र में रखा जाता है, तो बार नींद संबंधी विकार और अनिद्रा का कारण बनता है।',
              VastuStrings.bar9 : 'जब इस क्षेत्र में बार बनाया जाता है, तो व्यक्ति का पेय पीने का मोह समाप्त हो जाता है, साथ ही उसके जीवन में जीवंतता का एहसास भी खत्म हो जाता है।',
              VastuStrings.bar10 : 'घर के इस क्षेत्र में बने बार से आप अपने कौशल का सही ढंग से उपयोग करने में असमर्थ हो जाते हैं।',
              VastuStrings.bar11 : 'इस क्षेत्र में बना बार बच्चों की एकाग्रता और फोकस पर प्रतिकूल प्रभाव डालता है। उनका पढ़ाई से ध्यान भटक जाता है.',
              VastuStrings.bar12 : 'इस क्षेत्र में बार बनाने से परिवार को लाभ मिलता है। इसलिए, यह बार के लिए एक अच्छा क्षेत्र है।',
              VastuStrings.bar13 : 'यह आपके दिमाग को डिटॉक्सिफाई करने और आपकी अवरुद्ध भावनाओं और तनाव से छुटकारा पाने के लिए बार बनाने के लिए एक आदर्श क्षेत्र है। लेकिन लोग पीने के प्रति भी आकर्षित होते हैं.',
              VastuStrings.bar14 : 'जब इस क्षेत्र में एक बार बनाया जाता है, तो यह वांछित परिणाम देता है, खासकर निवासियों के लिए पेय या अल्कोहल पार्टियों में आयोजित बैठकों से।',
              VastuStrings.bar15 : 'घर के इस जोन में बना बार सेक्सुअल इंटिमेसी का मजा बढ़ाता है।',
              VastuStrings.bar16 : 'यह बार बनाने के लिए अनुमत क्षेत्र नहीं है, क्योंकि यह आपके करियर में आगामी विकास के अवसरों को बाधित करता है।',
              VastuStrings.television1 : 'इस क्षेत्र में टेलीविजन रखने से व्यक्ति स्वास्थ्य संबंधी चैनल देखता है और अपनी भलाई के बारे में अत्यधिक जागरूक हो जाता है। विडंबना यह है कि इसका परिणाम खराब स्वास्थ्य और कमजोर प्रतिरक्षा हो सकता है।',
              VastuStrings.television2 : 'यहां रखे गए टेलीविजन के साथ, एक व्यक्ति वास्तव में इसका अभ्यास करने के बजाय ध्यान के तरीकों और इससे जुड़ी विभिन्न तकनीकों के बारे में अधिक चिंतित होगा। वे इस विषय पर अधिक स्पष्टता की तलाश करेंगे।',
              VastuStrings.television3 : 'इस क्षेत्र में टेलीविजन रखना आदर्श है। यह एक जीवंत और ऊर्जावान वातावरण बनाता है, जो अधिकतम आनंद और ताज़गी प्रदान करता है',
              VastuStrings.television4 : 'इस क्षेत्र में टेलीविजन रखने से सामाजिक कनेक्टिविटी और दर्शकों की समग्र जागरूकता बढ़ती है। लोग अन्य मनोरंजन विकल्पों की तुलना में समाचार चैनलों को प्राथमिकता देते हैं। यह स्थान राजनीति से जुड़े व्यक्तियों के लिए विशेष लाभकारी है।',
              VastuStrings.television5 : 'इस क्षेत्र में टेलीविजन रखने से तनाव और चिंता को कम करने में मदद मिलती है। यहां टीवी रखने पर लोग डिस्कवरी चैनल और हिस्टोरिकल चैनल जैसे चैनल देखना पसंद करते हैं। वे टीवी कार्यक्रमों के माध्यम से अपने तनाव संबंधी मुद्दों का समाधान ढूंढते हैं।',
              VastuStrings.television6 : 'इस क्षेत्र में टेलीविजन लगाने से लोगों में वित्तीय मामलों से संबंधित कार्यक्रम और क्राइम रिपोर्टर, सनसनी और एक्शन फिल्में जैसे थ्रिलर देखने में रुचि बढ़ेगी।',
              VastuStrings.television7 : 'इस क्षेत्र में टेलीविजन रखने से लोग शारीरिक शक्ति से संबंधित कार्यक्रम, जैसे एरोबिक्स, योग, पोषण और अधिक शक्तिशाली और स्वस्थ बनने के उद्देश्य से इसी तरह की सामग्री देखना पसंद करेंगे।',
              VastuStrings.television8 : 'इस क्षेत्र में टेलीविजन रखने से व्यक्ति पूरी तरह से आराम कर सकता है और अच्छी नींद का आनंद ले सकता है।',
              VastuStrings.television9 : 'इस क्षेत्र में टेलीविजन रखने से समय और संसाधनों की पूरी बर्बादी हो सकती है। टेलीविज़न से प्राप्त जानकारी, जैसे शेयर बाज़ार अपडेट, के आधार पर लिए गए निर्णयों से हानि और नकारात्मक परिणाम हो सकते हैं। इसके अतिरिक्त, टेलीविजन में समय के साथ बार-बार तकनीकी समस्याएं उत्पन्न हो सकती हैं, जिसके लिए निरंतर आवश्यकता होती है',
              VastuStrings.television10 : 'इस क्षेत्र में टेलीविजन रखना कौशल बढ़ाने का काम करता है, क्योंकि व्यक्ति ऐसे कार्यक्रमों को देखने का आनंद लेते हैं जो उनके कौशल विकास में योगदान करते हैं।',
              VastuStrings.television11 : 'इस क्षेत्र में टेलीविजन रखने से बच्चों का ध्यान उनकी पढ़ाई और एकाग्रता से भटक सकता है, क्योंकि वे कार्टून और अन्य मनोरंजन कार्यक्रम देखने के लिए अधिक इच्छुक हो सकते हैं। हालाँकि, इसका उपयोग बच्चे शैक्षिक कार्यक्रम देखने के लिए भी कर सकते हैं।',
              VastuStrings.television12 : 'इस क्षेत्र में टेलीविज़न रखने से लोगों को टेलीविज़न कार्यक्रमों से बहुमूल्य जानकारी प्राप्त करने की अनुमति मिलती है, विशेष रूप से व्यापारिक व्यवसाय से जुड़े लोगों को लाभ होता है।',
              VastuStrings.television13 : 'इस क्षेत्र में टेलीविजन रखने से अवसाद और खराब मूड हो सकता है। फिल्में या टीवी शो देखते समय लोग भावुक हो सकते हैं और रोने लग सकते हैं।',
              VastuStrings.television14 : 'इस क्षेत्र में टेलीविजन रखने से लोगों को जरूरत पड़ने पर अपने उद्देश्यों के लिए समर्थन आकर्षित करने की क्षमता स्वाभाविक रूप से विकसित करने में मदद मिल सकती है।',
              VastuStrings.television15 : 'इस क्षेत्र में टेलीविजन रखने से वयस्क कार्यक्रम और अश्लील साहित्य देखने को मिल सकता है, जिससे संभावित रूप से लोग अपने जीवन में जो देखते हैं उसकी नकल करने के लिए प्रभावित हो सकते हैं।',
              VastuStrings.television16 : 'इस क्षेत्र में रखा गया टेलीविजन व्यक्ति को अपने करियर पर ध्यान केंद्रित करने में सक्षम बनाता है। वे नए अवसरों की तलाश करेंगे और कैरियर-उन्मुख कार्यक्रम देखने में संलग्न होंगे।',
              VastuStrings.computer1 : 'स्वास्थ्य संबंधी आवश्यक जानकारी प्राप्त करने के लिए यहां कंप्यूटर रखना उपयुक्त रहता है।',
              VastuStrings.computer2 : 'धार्मिक वेबसाइटें देखने या सर्फिंग के लिए उपयोग किए जाने पर यह क्षेत्र कंप्यूटर रखने के लिए उपयुक्त है। यह उस काम के लिए भी अनुकूल है जिसमें रचनात्मकता की आवश्यकता होती है और नए विचार उत्पन्न होते हैं।',
              VastuStrings.computer3 : 'यदि कंप्यूटर का उद्देश्य गेम खेलना, संगीत सुनना या मौज-मस्ती और आनंद लेना है, तो यह आदर्श क्षेत्र होना चाहिए।',
              VastuStrings.computer4 : 'यदि कंप्यूटर का उद्देश्य आपको शेष विश्व से जोड़ना और आपके आस-पास होने वाली घटनाओं के बारे में सूचित रहने में मदद करना है, तो इसे इसी क्षेत्र में रखा जाना चाहिए।',
              VastuStrings.computer5 : 'डेटा प्रविष्टि, जटिल गणना, अनुसंधान और विकास कार्य जैसे कार्यों के लिए कंप्यूटर का प्रभावी ढंग से उपयोग करने के लिए इसे इस क्षेत्र में रखा जाना चाहिए।',
              VastuStrings.computer6 : 'यह क्षेत्र नकदी संतुलन बनाए रखने के लिए आदर्श है।',
              VastuStrings.computer7 : 'दक्षिण-दक्षिणपूर्व (एसएसई) क्षेत्र में अतिथि शयनकक्ष बनाने की अनुमति है। इस क्षेत्र में बने अतिथि कक्ष में आप अपने मेहमानों के साथ अधिक सुरक्षित और मजबूत महसूस करेंगे।',
              VastuStrings.computer8 : 'इस क्षेत्र में रखे कंप्यूटर पर आप जो भी काम करेंगे, वह आपको प्रशंसा और प्रसिद्धि दिलाएगा।',
              VastuStrings.computer9 : 'यहां रखा कंप्यूटर नियमित रूप से उपयोग नहीं किया जाएगा और उसे बार-बार मरम्मत की आवश्यकता होगी। इस पर किया गया काम नुकसान का कारण बनेगा, खासकर शेयर और ट्रेडिंग से जुड़े लोगों को।',
              VastuStrings.computer10 : 'यदि डिज़ाइनिंग जैसे कुशल कार्य के लिए उपयोग किया जाए तो यहां रखा कंप्यूटर आदर्श है। यह कौशल को बढ़ाने में मदद करता है और बेहतर परिणाम देता है।',
              VastuStrings.computer11 : 'यह ज्ञान प्राप्त करने के लिए अच्छा है-बच्चे इसका उपयोग शैक्षिक उद्देश्यों के लिए भी कर सकते हैं। अकाउंटेंसी के लिए यह विशेष रूप से फायदेमंद है।',
              VastuStrings.computer12 : 'इस क्षेत्र में कंप्यूटर के माध्यम से प्राप्त जानकारी विशेष रूप से शेयर बाजार व्यवसाय से जुड़े लोगों के लिए काफी फायदेमंद होगी।',
              VastuStrings.computer13 : 'इस क्षेत्र में रखे गए कंप्यूटर का उपयोग खराब मूड, तनाव और अवसाद से निपटने के लिए सबसे अच्छा किया जा सकता है।',
              VastuStrings.computer14 : 'जब भी आपको आवश्यकता हो इस क्षेत्र में एक कंप्यूटर मददगार साबित होता है। यह आपको आपके संपर्कों से समय पर सहायता भी प्रदान करता है।',
              VastuStrings.computer15 : 'यहां रखे एक कंप्यूटर का इस्तेमाल पोर्नोग्राफी देखने और उससे आनंद लेने के लिए किया जाएगा। इसलिए, बढ़ते बच्चों द्वारा इंटरनेट पर अवांछित सर्फिंग से बचने के लिए इसे इस क्षेत्र में रखने से बचना चाहिए।',
              VastuStrings.computer16 : 'उत्तर दिशा में कंप्यूटर रखना करियर संबंधी गतिविधियों और जीवन में नए अवसरों की खोज के लिए फायदेमंद है।',
              VastuStrings.staircase1 : 'इस क्षेत्र में वामावर्त सीढ़ियाँ निवासियों की समग्र प्रतिरक्षा में सुधार करती हैं। इससे उन्हें अपनी बीमारियों से तेजी से उबरने में मदद मिलती है।',
              VastuStrings.staircase2 : 'इस क्षेत्र में एंटी-क्लॉकवाइज सीढ़ियाँ विचारों को अधिक स्पष्टता प्रदान करती हैं, नए विचार लाती हैं और उपयोगकर्ताओं के लिए रचनात्मकता बढ़ाती हैं।',
              VastuStrings.staircase3 : 'इस क्षेत्र में बनी एंटी-क्लॉकवाइज सीढ़ियाँ परिवार के लिए अधिक खुशी, खुशी और मनोरंजन लाती हैं।',
              VastuStrings.staircase4 : 'इस क्षेत्र में एंटी-क्लॉकवाइज सीढ़ियाँ होना अच्छा है, क्योंकि इससे सामाजिक संपर्क बेहतर होता है और समाज के साथ संबंध लाभदायक होते हैं। इससे आपको जीवन में आगे बढ़ने में भी मदद मिलती है. यहां बनी क्लॉकवाइज सीढ़ियां चिंता और मन की अवांछित या अनावश्यक प्रक्रिया को कम करती हैं। यदि सीढ़ियां एंटी-क्लॉकवाइज बनाई जाएं तो इसका विपरीत होता है।',
              VastuStrings.staircase5 : 'इस क्षेत्र में बनी घड़ी की दिशा में बनी सीढ़ियां जीवन में आ रही अतिरिक्त उलझनों को दूर करती हैं',
              VastuStrings.staircase6 : 'इस क्षेत्र में बनी दक्षिणावर्त सीढ़ियाँ निवासियों के अत्यधिक क्रोध और आक्रामकता को नियंत्रित करने में मदद करती हैं। यदि सीढ़ियाँ एंटी-क्लॉकवाइज़ बनाई जाती हैं तो इसका विपरीत होता है।',
              VastuStrings.staircase7 : 'यहां बनी एंटी-क्लॉकवाइज सीढ़ियां निवासियों की मानसिक और शारीरिक शक्ति को बढ़ाती हैं, जिससे उनके आत्मविश्वास के स्तर को बढ़ाने में मदद मिलती है।',
              VastuStrings.staircase8 : 'इस क्षेत्र में दक्षिणावर्त सीढ़ियाँ निवासियों के लिए प्रसिद्धि और सद्भावना लाती हैं, और उन्हें उनके प्रयासों के लिए उचित मान्यता मिलती है। यहां एंटी-क्लॉकवाइज सीढ़ियां खराब प्रतिष्ठा का कारण बन सकती हैं, जिससे लोगों के लिए आराम महसूस करना मुश्किल हो जाता है।',
              VastuStrings.staircase9 : 'इस क्षेत्र में सीढ़ियां हमेशा क्लॉकवाइज बनानी चाहिए। इससे संसाधनों और प्रयासों की बर्बादी कम होती है और दक्षता में सुधार करने में मदद मिलती है।',
              VastuStrings.staircase10 : 'इस क्षेत्र में बनी दक्षिणावर्त सीढ़ियाँ करियर, रिश्तों और समग्र रूप से जीवन में स्थिरता प्रदान करती हैं। निवासियों को अपने कौशल और विशेषज्ञता का उपयोग करने और उन्हें तेज करने की इच्छा होती है।',
              VastuStrings.staircase11 : 'घर के इस क्षेत्र में बनी दक्षिणावर्त सीढ़ियाँ व्यक्ति को यह जानने में मदद करती हैं कि उसे अपने कौशल का कितना अभ्यास करना चाहिए और अभ्यास/प्रयासों को वांछित परिणामों की ओर ले जाना चाहिए। शैक्षणिक संस्थानों जैसे स्थानों के लिए एंटी-क्लॉकवाइज सीढ़ियों की सिफारिश की जाती है।',
              VastuStrings.staircase12 : 'यहां बनी एंटी-क्लॉकवाइज सीढ़ियां निवासियों के भौतिक लाभ को बढ़ाती हैं। यहां किए गए प्रत्येक प्रयास का परिणाम उपयोगी और वांछित होता है।',
              VastuStrings.staircase13 : 'इस क्षेत्र में दक्षिणावर्त सीढ़ियाँ निवासियों के भावनात्मक संतुलन को बनाए रखने में मदद करती हैं। यह छोटी-छोटी बातों पर रोने की उनकी प्रवृत्ति को कम करने में भी मदद करता है।',
              VastuStrings.staircase14 : 'इस क्षेत्र में दक्षिणावर्त सीढ़ियाँ निवासियों को उनके व्यक्तिगत और व्यावसायिक जीवन में आवश्यकता पड़ने पर सहायता और समर्थन की सुविधा प्रदान करती हैं।',
              VastuStrings.staircase15 : 'घर के इस क्षेत्र में सीढ़ियाँ एंटी-क्लॉकवाइज होनी चाहिए, क्योंकि यह रहने वाले जोड़े या जोड़ों के बीच मजबूत और प्रेमपूर्ण रिश्ते की नींव बनाती है।',
              VastuStrings.staircase16 : 'इस दिशा में बनी वामावर्त सीढ़ियाँ करियर और समग्र जीवन विकास के अवसर पैदा करने में मदद करती हैं।',
              VastuStrings.heater1 : 'हीलिंग जोन में हीटर रखने से बीमारियाँ आकर्षित हो सकती हैं और रोग प्रतिरोधक क्षमता कमजोर हो सकती है। निवासियों को चल रही दवा से मुक्त होने के लिए संघर्ष करना पड़ सकता है।',
              VastuStrings.heater2 : 'इस क्षेत्र में हीटर स्थापित करने से निवासियों की मानसिक शांति भंग हो सकती है। इससे भ्रम, अस्पष्ट सोच, भविष्य की योजना बनाने में कठिनाई और चिड़चिड़ा व्यवहार हो सकता है। लोग उचित विचार किए बिना जल्दबाजी में निष्कर्ष पर पहुंच जाते हैं, जिससे बाद में उन्हें परेशानी हो सकती है।',
              VastuStrings.heater3 : 'इस क्षेत्र में हीटर होने से निवासियों की मौज-मस्ती और खुशी खोजने की कोशिशें निराशा और आक्रामकता में बदल जाती हैं। उन्हें ताज़गी की निरंतर आवश्यकता महसूस होती है लेकिन वे इसे अपने जीवन में प्राप्त करने के लिए संघर्ष करते हैं।',
              VastuStrings.heater4 : 'इस क्षेत्र में हीटर रखना स्वीकार्य है। यह वित्तीय लाभ और सामाजिक संपर्क के मामले में मध्यम परिणाम देता है।',
              VastuStrings.heater5 : 'इस क्षेत्र में हीटर रखने से अत्यधिक सोचने और अत्यधिक विश्लेषण करने की प्रवृत्ति बढ़ जाती है। व्यक्ति अपने समय और ऊर्जा को उपयोगी और लाभकारी विचारों की ओर निर्देशित करने के लिए संघर्ष करते हैं। इसके परिणामस्वरूप परिवार के सदस्यों और अन्य रिश्तों के बीच बार-बार झगड़े और असहमति हो सकती है।',
              VastuStrings.heater6 : 'इस क्षेत्र में हीटर रखना आदर्श है। यह हाथ में नकदी की उपलब्धता में सुधार करता है और अवरुद्ध भुगतानों की वसूली की सुविधा प्रदान करता है।',
              VastuStrings.heater7 : 'इस क्षेत्र में हीटर लगाने से निवासियों को शक्ति, आत्मविश्वास और सुरक्षा की भावना मिलती है। यह शारीरिक और मानसिक शक्ति दोनों को बढ़ाता है।',
              VastuStrings.heater8 : 'इस क्षेत्र में हीटर लगाने से निवासियों को आरामदायक नींद का आनंद मिलता है और उनके प्रयासों के लिए उचित मान्यता प्राप्त होती है।',
              VastuStrings.heater9 : 'इस क्षेत्र में हीटर रखने से निवासियों के लिए कोई विशेष उद्देश्य पूरा नहीं होता है। यदि इसका उपयोग किया जाए तो यह घर में रहने वालों के लिए अनावश्यक खर्चों को बढ़ा देता है।',
              VastuStrings.heater10 : 'इस क्षेत्र में हीटर रखना रिश्तों में अस्थिरता का मूल कारण बनता है। इससे परिवार के सदस्यों के बीच अवांछित गरमागरम बहस होती है। इससे कार्यस्थल पर खराब प्रदर्शन भी होता है जिससे करियर में अस्थिरता आती है।',
              VastuStrings.heater11 : 'इस जोन में रखा गया हीटर आपकी बचत पर बुरा असर डालता है। इसके अलावा, आपके बच्चों को पढ़ाई में अपना सर्वश्रेष्ठ प्रयास करने के बावजूद अच्छे अंक प्राप्त करने में कठिनाई होती है।',
              VastuStrings.heater12 : 'लाभ और मुनाफ़े के क्षेत्र में हीटर रखने से आपको अपनी सारी मेहनत का फल प्राप्त करने में समस्याएँ आती हैं। आपको अनुभव होता है कि किसी कारणवश आप अपना कार्य सफलतापूर्वक पूरा नहीं कर पाते हैं, जिससे आपको अपनी मेहनत का वांछित परिणाम नहीं मिल पाता है।',
              VastuStrings.heater13 : 'इस क्षेत्र में हीटर रखना फायदेमंद है, क्योंकि यह आपके खराब मूड और नकारात्मक विचारों को दूर करने में मदद करता है। यह आपकी अवरुद्ध भावनाओं को जला देता है और आपके दिमाग को प्रतिकूल भावनात्मक स्थितियों का सामना करने के लिए सशक्त बनाता है।',
              VastuStrings.heater14 : 'अपने घर के इस क्षेत्र में हीटर रखने से लोग आपसे दूर रहना पसंद करते हैं, खासकर जब आपको उनके समर्थन की आवश्यकता होती है। आपको अपने निवेश पर रिटर्न पाने में भी बाधाओं का सामना करना पड़ सकता है।',
              VastuStrings.heater15 : 'जब सेक्स के क्षेत्र में हीटर रखा जाता है, तो अंतरंग क्षणों में जुनून आपके साथी के साथ तीखी बहस, शिकायतें और असंतोष का कारण बन सकता है। यह अनावश्यक तनाव निवासी जोड़ों के बीच दरार पैदा कर सकता है।',
              VastuStrings.heater16 : 'इस क्षेत्र में हीटर रखने से करियर के विकास में बाधा आ सकती है और नौकरी के अच्छे अवसर सुरक्षित करना चुनौतीपूर्ण हो सकता है। व्यवसाय मालिकों के लिए, नए ग्राहकों को आकर्षित करना, नए ऑर्डर प्राप्त करना और भुगतान की वसूली करना अधिक कठिन हो सकता है।',
              VastuStrings.inverter1 : 'एनएनई ज़ोन में इन्वर्टर रखने से खांसी, कंजेशन और सांस संबंधी अन्य परेशानियां जैसी स्वास्थ्य समस्याएं हो सकती हैं। इसके अतिरिक्त, यह आपातकालीन स्थितियाँ पैदा कर सकता है जहाँ तत्काल चिकित्सा सहायता की आवश्यकता होती है।',
              VastuStrings.inverter2 : 'पूर्वोत्तर क्षेत्र में इन्वर्टर रखने से व्यक्ति विशिष्ट विषयों पर मानसिक स्पष्टता खो सकता है। निर्णय लेते समय सहायता के लिए वे दूसरों पर निर्भर हो सकते हैं।',
              VastuStrings.inverter3 : 'ईएनई ज़ोन में इन्वर्टर रखने से जीवन मौज-मस्ती और खुशी से रहित हो सकता है। आपको खुद को तरोताजा करना चुनौतीपूर्ण लग सकता है, भले ही आप ऐसा करने के उद्देश्य से बाहर जाएं।',
              VastuStrings.inverter4 : 'पूर्व दिशा में इन्वर्टर रखने से ऐसी स्थिति पैदा हो सकती है जहां व्यक्ति बार-बार अपने संपर्कों से मदद मांगता है। इससे समाज में उनकी छवि पर नकारात्मक प्रभाव पड़ सकता है और उनके सामाजिक संपर्क कमजोर हो सकते हैं।',
              VastuStrings.inverter5 : 'ईएसई क्षेत्र में इन्वर्टर रखना आपात स्थिति में सहायक हो सकता है, क्योंकि इससे आपको सहायता मिलती है। हालाँकि, यदि इन्वर्टर ख़राब है, तो इससे परिवार के लिए कानूनी समस्याएँ पैदा हो सकती हैं।',
              VastuStrings.inverter6 : 'एसई क्षेत्र में इन्वर्टर रखना स्वीकार्य है, लेकिन यदि यह ख़राब है, तो यह निवासियों के लिए तरल नकदी की उपलब्धता को बाधित कर सकता है।',
              VastuStrings.inverter7 : 'एक इन्वर्टर को एसएसई क्षेत्र में रखा जा सकता है, लेकिन लोगों को आत्मविश्वास की हानि का अनुभव हो सकता है और जरूरत के समय में उन्हें ताकत और सहायता प्रदान करने के लिए दूसरों पर भरोसा करना पड़ सकता है।',
              VastuStrings.inverter8 : 'दक्षिण क्षेत्र में इन्वर्टर रखे जाने से व्यक्ति को तनाव महसूस होगा और आराम पाने की जल्दी होगी।',
              VastuStrings.inverter9 : 'एसएसडब्ल्यू जोन में रखे गए इन्वर्टर से जरूरत पड़ने पर मदद नहीं मिल पाएगी, खर्च बढ़ जाएगा और इन्वर्टर में बार-बार खराबी आ जाएगी।',
              VastuStrings.inverter10 : 'एसडब्ल्यू जोन में रखा इन्वर्टर व्यक्तियों को इस तरह से प्रभावित करता है कि वे अपने कौशल का उपयोग करने में झिझकने लगते हैं और अक्सर अपने कार्यों को पूरा करने के लिए दूसरों की मदद लेते हैं।',
              VastuStrings.inverter11 : 'डब्ल्यूएसडब्ल्यू क्षेत्र में, एक इन्वर्टर एक छात्र को पूरे वर्ष लगातार दूसरों की मदद करने के लिए प्रेरित करता है। हालाँकि, परीक्षाओं के दौरान, छात्र अपने नोट्स और अन्य प्रकार की सहायता के लिए दोस्तों से सहायता ले सकते हैं।',
              VastuStrings.inverter12 : 'इस क्षेत्र में रखा इन्वर्टर परिवार के लिए नियमित लाभ को अवरुद्ध कर सकता है। हालाँकि, लाभ अभी भी आएगा, लेकिन वे तभी आ सकते हैं जब परिवार को उनकी सख्त जरूरत हो।',
              VastuStrings.inverter13 : 'यहां इन्वर्टर रखने से यह सुनिश्चित होता है कि जब भी आपको जरूरत हो, भावनात्मक समर्थन के लिए आपके पास कोई है।',
              VastuStrings.inverter14 : 'इन्वर्टर के लिए यह एक आदर्श क्षेत्र है। यह समय पर सहायता और सहायता सुनिश्चित करता है।',
              VastuStrings.inverter15 : 'यहां इन्वर्टर रखने से लोग सेक्स का आनंद लेने के बजाय इसे तनाव से राहत के साधन के रूप में उपयोग कर सकते हैं।',
              VastuStrings.inverter16 : 'उत्तर क्षेत्र में इन्वर्टर रखने से आपके करियर के विकास में बाधा आ सकती है। इससे ऐसी स्थिति उत्पन्न हो सकती है जहां आप अपने करियर को आगे बढ़ाने और स्थिरता बनाए रखने में सहायता के लिए दूसरों पर अधिक निर्भर हो जाएंगे। यदि इन्वर्टर ख़राब हो जाता है या काम करना बंद कर देता है, तो आप पाएंगे कि दूसरों से सहायता आसानी से उपलब्ध नहीं है।',
              VastuStrings.ac1 : 'यह क्षेत्र एयर कंडीशनर स्थापित करने के लिए भी उपयुक्त है, क्योंकि इसका कोई प्रतिकूल प्रभाव नहीं पड़ता है',
              VastuStrings.ac2 : 'यह एयर कंडीशनर (एसी) स्थापित करने के लिए उपयुक्त स्थान नहीं है, क्योंकि इससे निवासियों को चिंता और मानसिक अस्थिरता हो सकती है।',
              VastuStrings.ac3 : 'इस क्षेत्र में बिना किसी प्रतिकूल प्रभाव के एसी लगाया जा सकता है।',
              VastuStrings.ac4 : 'एयर कंडीशनर (एसी) स्थापित करने के लिए यह एक स्वीकार्य क्षेत्र है क्योंकि इसका कोई प्रतिकूल प्रभाव नहीं पड़ता है।',
              VastuStrings.ac5 : 'यह क्षेत्र बिना किसी नकारात्मक परिणाम के एयर कंडीशनर लगाने के लिए उपयुक्त है।',
              VastuStrings.ac6 : 'इस क्षेत्र में एयर कंडीशनर (एसी) रखने से नकदी प्रवाह की समस्या होती है और बचत पर नकारात्मक प्रभाव पड़ता है। इसलिए यहां एसी लगाने से बचने की सलाह दी जाती है।',
              VastuStrings.ac7 : 'इस क्षेत्र में रखे जाने पर एयर कंडीशनर पर कोई प्रतिकूल प्रभाव नहीं पड़ता है, जिससे यह एसी स्थापित करने के लिए उपयुक्त क्षेत्र बन जाता है।',
              VastuStrings.ac8 : 'अग्नि तत्व से संबंधित होने के कारण यह एसी लगाने के लिए भी अनुमत क्षेत्र है।',
              VastuStrings.ac9 : 'यह एयर कंडीशनर स्थापित करने के लिए अनुमत क्षेत्र है।',
              VastuStrings.ac10 : 'इस क्षेत्र में एयर कंडीशनर होने से निवासी काम करते समय अत्यधिक आराम की तलाश कर सकते हैं, जो आदर्श नहीं हो सकता है।',
              VastuStrings.ac11 : 'यह क्षेत्र एयर कंडीशनर की स्थापना की अनुमति देता है क्योंकि इसका कोई प्रतिकूल प्रभाव नहीं पड़ता है।',
              VastuStrings.ac12 : 'इस क्षेत्र में एयर कंडीशनर लगाने से कोई नकारात्मक प्रभाव नहीं पड़ता है, इसलिए इसकी अनुमति है।',
              VastuStrings.ac13 : 'यह क्षेत्र एयर कंडीशनर स्थापित करने के लिए भी अनुमत है क्योंकि इससे कोई प्रतिकूल प्रभाव नहीं पड़ता है।',
              VastuStrings.ac14 : 'इस क्षेत्र में एयर कंडीशनर लगाने की अनुमति है।',
              VastuStrings.ac15 : 'इस क्षेत्र में एयर कंडीशनर का कोई प्रतिकूल प्रभाव नहीं पड़ता है, इसलिए इसे यहां रखा जा सकता है।',
              VastuStrings.ac16 : 'इस क्षेत्र में एयर कंडीशनर रखने से कोई नकारात्मक प्रभाव नहीं जुड़ा है।',
              VastuStrings.diningPlace1 : 'निवासी अपने स्वास्थ्य के प्रति अधिक जागरूक और अपने आहार के प्रति सावधान हो जाते हैं।',
              VastuStrings.diningPlace2 : 'धार्मिक पहलू को ध्यान में रखते हुए अधिक सात्विक एवं शाकाहारी भोजन करें।',
              VastuStrings.diningPlace3 : 'रहने वाला भोजन का आनंद उठाएगा और पोषण संबंधी तथ्यों को ध्यान में नहीं रखेगा। इससे खासकर बच्चों में जंक फूड की आदत बढ़ सकती है।',
              VastuStrings.diningPlace4 : 'यह क्षेत्र सामाजिक समारोहों को प्रोत्साहित करता है।',
              VastuStrings.diningPlace5 : 'व्यक्ति भोजन के स्वाद के बारे में अधिक विश्लेषणात्मक बनेगा। जिससे भोजन को लेकर विवाद होता है।',
              VastuStrings.diningPlace6 : 'इस क्षेत्र में एक डाइनिंग हॉल ऐपेटाइज़र के रूप में काम करता है। लोग समय पर भोजन करने का प्रयास करते हैं। यह पाचन में सुधार करता है, लेकिन व्यक्ति को स्वभाव में अधिक आक्रामक बना देता है।',
              VastuStrings.diningPlace7 : 'भोजन क्षेत्र के लिए बहुत अच्छा क्षेत्र। इससे खाना आसानी से पच जाता है और शरीर को जरूरी पोषक तत्व और ताकत भी मिलती है।',
              VastuStrings.diningPlace8 : 'यह फिर से भोजन के लिए एक अच्छा क्षेत्र है। भोजन ठीक से पचता है और लोग अपने जीवन में मानसिक शांति के साथ आराम महसूस करते हैं।',
              VastuStrings.diningPlace9 : 'यहां खाया जाने वाला खाना शरीर को कोई ताकत या पोषण नहीं देता और स्वास्थ्य संबंधी समस्याएं पैदा करता है।',
              VastuStrings.diningPlace10 : 'डाइनिंग टेबल रखने के लिए यह अच्छा क्षेत्र नहीं है। यहां भोजन करने से परिवार में रिश्ते संबंधी समस्याएं पैदा होती हैं। पिता अपने बच्चों को टेबल मैनर्स न होने के लिए डांटेगा, और उसकी पत्नी अपने बच्चों को ठीक से शिक्षित न करने के लिए डांटेगी, इत्यादि।',
              VastuStrings.diningPlace11 : 'लोग खाना खाने के उचित शिष्टाचार और टेबल मैनर्स को लेकर बहुत सावधान हो जाते हैं।',
              VastuStrings.diningPlace12 : 'भोजन क्षेत्र के लिए अच्छा क्षेत्र। यहां खाया गया भोजन पोषक तत्वों के अवशोषण को सुनिश्चित करेगा और इस प्रकार, अच्छा स्वास्थ्य प्राप्त होगा।',
              VastuStrings.diningPlace13 : 'भोजन के संबंध में रहने वाले की सोच नकारात्मक हो जाती है।',
              VastuStrings.diningPlace14 : 'आवश्यकता पड़ने पर रहने वालों को समर्थन और सहायता मिलती है, जिससे उनकी इच्छाएं पूरी होती हैं।',
              VastuStrings.diningPlace15 : 'यहां भोजन करने वाले लोग हर बार नई और अलग-अलग तैयारियों का स्वाद चखेंगे और अपने भोजन का आनंद लेंगे।',
              VastuStrings.diningPlace16 : 'अधिभोगी करियर पर अधिक ध्यान केंद्रित करता है और जीवन की उलझनों को पीछे छोड़ देता है। इस क्षेत्र में पाचन थोड़ा खराब रहेगा।',
              VastuStrings.drawingRoom1 : 'उत्तर-उत्तर-पूर्व (एनएनई) दिशा में स्थित ड्राइंग रूम के निवासियों को अक्सर आगंतुकों से बेहतर स्वास्थ्य के लिए सुझाव मिलते हैं। हालाँकि, सोफे और अन्य साज-सामान के रंग पर ध्यान देना ज़रूरी है, क्योंकि कुछ रंग, जैसे लाल, उनके स्वास्थ्य पर प्रतिकूल प्रभाव डाल सकते हैं।',
              VastuStrings.drawingRoom2 : 'उत्तर-पूर्व दिशा में स्थित ड्राइंग रूम आध्यात्मिकता और धर्म से संबंधित चर्चाओं को प्रोत्साहित करता है। ऐसे ड्राइंग रूम के निवासियों के धार्मिक व्यक्तियों से जुड़ने की अधिक संभावना होती है।',
              VastuStrings.drawingRoom3 : 'पूर्व-उत्तर-पूर्व दिशा में स्थित एक ड्राइंग रूम मेहमानों और आगंतुकों की मेजबानी के लिए आदर्श है। यह एक स्वागत योग्य माहौल बनाता है जहां गृहस्वामी पारिवारिक समारोहों और सामाजिक कार्यक्रमों का आनंद ले सकता है।',
              VastuStrings.drawingRoom4 : 'पूर्व दिशा ड्राइंग रूम के लिए आदर्श स्थान है। जो लोग ऐसे ड्राइंग रूम में इकट्ठा होते हैं वे मजबूत संबंध और समझ बनाते हैं जो समय के साथ और मजबूत होते जाते हैं। इस क्षेत्र में बने सामाजिक बंधन स्थायी और लंबे समय तक चलने वाले होते हैं।',
              VastuStrings.drawingRoom5 : 'मंथन क्षेत्र (ईएसई) के रूप में जाने जाने वाले इस क्षेत्र में आयोजित बैठकें अनुत्पादक होती हैं। यहां होने वाली चर्चाओं से अक्सर कोई उपयोगी निष्कर्ष नहीं निकलता।',
              VastuStrings.drawingRoom6 : 'दक्षिण-पूर्व (एसई) दिशा में आयोजित बैठकें सकारात्मक परिणाम देती हैं, लेकिन चर्चाएँ काफी गहन और शांतिपूर्ण नहीं हो सकती हैं',
              VastuStrings.drawingRoom7 : 'दक्षिण-दक्षिणपूर्व (एसएसई) दिशा में आयोजित बैठकों में सर्वसम्मति से समझौते होते हैं, और चर्चा शांतिपूर्ण और सम्मानजनक तरीके से आयोजित की जाती है।',
              VastuStrings.drawingRoom8 : 'दक्षिण दिशा में बैठकें अधिक आरामदायक होती हैं।',
              VastuStrings.drawingRoom9 : 'दक्षिण-दक्षिण-पश्चिम (SSW) दिशा को निपटान क्षेत्र माना जाता है। यदि इस क्षेत्र में ड्राइंग रूम स्थित है तो आर्थिक नुकसान हो सकता है।',
              VastuStrings.drawingRoom10 : 'दक्षिण-पश्चिम (एसडब्ल्यू) दिशा में होने वाली चर्चाएँ अक्सर पारिवारिक मामलों, रिश्तों, पैतृक विषयों और समग्र रूप से करियर और जीवन दोनों में स्थिरता के आसपास घूमती हैं।',
              VastuStrings.drawingRoom11 : 'पश्चिम-दक्षिण-पश्चिम (WSW) दिशा में, चर्चाएँ अक्सर शिक्षा से संबंधित विषयों, विशेष रूप से उनके बच्चों की शिक्षा, साथ ही सरकार से संबंधित मुद्दों के इर्द-गिर्द घूमती हैं।',
              VastuStrings.drawingRoom12 : 'पश्चिम दिशा में की गई बैठकें अधिक उत्पादक होती हैं और सकारात्मक परिणाम देती हैं।',
              VastuStrings.drawingRoom13 : 'पश्चिम-उत्तर-पश्चिम (डब्ल्यूएनडब्ल्यू) दिशा में स्थित ड्राइंग रूम अक्सर रेचन के लिए स्थान के रूप में काम करते हैं। इस दिशा के घरों में रहने वाले लोग अपने जीवन की समस्याओं, चुनौतियों और कठिनाइयों को साझा करते हैं',
              VastuStrings.drawingRoom14 : 'उत्तर-पश्चिम (एनडब्ल्यू) दिशा में आयोजित बैठकें, विशेष रूप से बातचीत से जुड़ी बैठकें, निवासियों के लिए फलदायी और अनुकूल होने की संभावना है। इस ड्राइंग रूम में बैठकर सहायता मांगने से आगंतुकों के लिए मना करना मुश्किल हो सकता है।',
              VastuStrings.drawingRoom15 : 'उत्तर-उत्तर-पश्चिम (एनएनडब्ल्यू) दिशा में स्थित एक ड्राइंग रूम अपने उपयोगकर्ताओं को इस तरह से प्रभावित करता है कि वे अक्सर अपने लिए मौद्रिक लाभ की तलाश किए बिना बैठकों में शामिल होते हैं और दूसरों की मदद करते हैं। फिर भी, उन्हें अपनी पसंद के विषयों पर चर्चा करने में खुशी मिलती है।',
              VastuStrings.drawingRoom16 : 'जब लोग उत्तर दिशा में स्थित ड्राइंग रूम में बैठकर विभिन्न विषयों पर चर्चा करते हैं, तो अक्सर पैसा कमाने के नए अवसर और संभावनाएं सामने आती हैं, जो चर्चा में शामिल सभी लोगों के कौशल और क्षमताओं का लाभ उठाते हैं।',
              VastuStrings.storeRoom1 : 'इस क्षेत्र में एक स्टोर निवासियों के स्वास्थ्य पर प्रतिकूल प्रभाव डाल सकता है और इसलिए इससे बचना चाहिए।',
              VastuStrings.storeRoom2 : 'इस क्षेत्र में मन की स्पष्टता का अभाव होता है और आमतौर पर मन अवरुद्ध हो जाता है।',
              VastuStrings.storeRoom3 : 'यहां का स्टोर रूम सुस्ती, विलंब और सुख से विरक्ति का कारण बनेगा।',
              VastuStrings.storeRoom4 : 'आपके सामाजिक संबंध कमजोर होंगे और संबंध बनाने में आपको कुछ भी अच्छा नहीं लगेगा।',
              VastuStrings.storeRoom5 : 'इस क्षेत्र में एक स्टोर स्थित हो सकता है। इस क्षेत्र में एक स्टोर चिंता और विचारों के अवांछित प्रवाह को कम करता है जो जीवन में तनाव पैदा कर सकता है',
              VastuStrings.storeRoom6 : 'इस क्षेत्र में दुकान होने से व्यापार के विस्तार और धन के आगमन में बाधा आती है। एसटीसी व्यवसाय में अवरुद्ध भुगतान का भी कारण बनता है। इसलिए, हौशेन के निवासी भविष्य के लिए धन संचय करने और व्यय से बचने का प्रयास करेंगे। यदि आप सेवा क्षेत्र में हैं, तो दक्षिण पूर्व में स्टोर आपकी नौकरी सुरक्षित कर सकता है।',
              VastuStrings.storeRoom7 : 'इस क्षेत्र में एक स्टोर अच्छा है. इस क्षेत्र में यह शक्ति, आत्मविश्वास और सुरक्षा की भावना देता है।',
              VastuStrings.storeRoom8 : 'इस क्षेत्र में स्टोर करना अच्छा है और अगर व्यवस्थित रखा जाए तो आराम मिलता है।',
              VastuStrings.storeRoom9 : 'आप इस क्षेत्र में डिस्पोजेबल और अवांछित चीजों के लिए स्टोर बना सकते हैं, लेकिन सुनिश्चित करें कि आपको यहां कोई भी कीमती सामान या महत्वपूर्ण दस्तावेज नहीं रखने चाहिए।',
              VastuStrings.storeRoom10 : 'यह क्षेत्र मूल्यवान चीजों और आपके कौशल से जुड़ी चीजों के भंडारण के लिए अच्छा है। साफ-सुथरा और व्यवस्थित स्टोर बनाया जा सकता है लेकिन कबाड़ और बेकार चीजों से बचें।',
              VastuStrings.storeRoom11 : 'स्टोर के लिए भी यह बहुत अच्छी जगह है. फिर, यहां कोई कबाड़ या बेकार वस्तु नहीं, बल्कि उपयोगी वस्तुएं संग्रहित की जानी चाहिए।',
              VastuStrings.storeRoom12 : 'यदि इस क्षेत्र में कबाड़ न रखा जाए तो दुकान में रहने वालों को सुरक्षित लाभ मिलता है। लोहा सुरक्षित रखें, या अन्य महत्वपूर्ण सामान रखें।',
              VastuStrings.storeRoom13 : 'स्टोर के लिए अच्छी जगह, भावनाओं और खराब मूड पर काबू पाने में मदद करती है।',
              VastuStrings.storeRoom14 : 'यह स्टोर के लिए एक आदर्श स्थान है. जैसा कि विश्वकर्मा प्रकाश में बताया गया है, यह किसी भी प्रकार के भंडारण के लिए सर्वोत्तम क्षेत्र है। इस क्षेत्र में एक स्टोर मददगार लोगों को उनके जीवन में लाता है।',
              VastuStrings.storeRoom15 : 'इस क्षेत्र में स्टोर की सलाह नहीं दी जाती है। एक व्यवस्थित स्टोर कम समस्याग्रस्त हो सकता है, लेकिन इस क्षेत्र में कबाड़ का स्टोर रखने से महिलाओं में घर के बाहर पुरुष साथी की तलाश बढ़ जाएगी। एक दुकान में विभिन्न प्रकार की वस्तुएं होती हैं जिनमें विभिन्न धातुएं और आकार होते हैं।',
              VastuStrings.storeRoom16 : 'यह करियर के विकास और धन के प्रवाह में बाधा उत्पन्न कर सकता है।',
              VastuStrings.boreWell1 : 'उत्तर-उत्तर-पूर्व में बोरवेल पवित्र स्प्राइट जल का स्रोत है।',
              VastuStrings.boreWell2 : 'उत्तर पूर्व में 45 डिग्री पर बोरवेल करना अच्छा नहीं है। यह 40 या 50 डिग्री पर होना चाहिए.',
              VastuStrings.boreWell3 : 'ईएनई में बोरवेल होने से परिवार में खुशी का माहौल है',
              VastuStrings.boreWell4 : 'पूर्व दिशा में बोरवेल करके प्रचलन प्राप्त किया जा सकता है।',
              VastuStrings.boreWell5 : 'ईएसई में बोरवेल के कारण पारिवारिक विवाद उत्पन्न हो सकते हैं।',
              VastuStrings.boreWell6 : 'एसई में बोरवेल से नकदी की समस्या और महिला प्रभुत्व की समस्या पैदा होती है।',
              VastuStrings.boreWell7 : 'एसएसई में बोरवेल के कारण दुर्घटनाएं हो सकती हैं',
              VastuStrings.boreWell8 : 'रक्त संबंधी लाइलाज बीमारी दक्षिण में बोरवेल का परिणाम है।',
              VastuStrings.boreWell9 : 'एसएसडब्ल्यू में बोरवेल से नकारात्मक परिणाम हो सकते हैं।',
              VastuStrings.boreWell10 : 'SW में बोरवेल के कारण रिश्ते में समस्याएँ उत्पन्न हो सकती हैं। और परिवार का मुख्य मुखिया किसी रोग से पीड़ित हो सकता है।',
              VastuStrings.boreWell11 : 'डब्ल्यूएसडब्ल्यू में बोरिंग कुओं के परिणामस्वरूप धन में कमी हो सकती है।',
              VastuStrings.boreWell12 : 'पश्चिम में बोरिंग कुएँ हानिकारक या लाभकारी नहीं हैं, वे औसत के बराबर हैं।',
              VastuStrings.boreWell13 : 'WNW में बोरवेल के कारण परिवार को दुःख का अनुभव होता है।',
              VastuStrings.boreWell14 : 'आपकी सार्वजनिक छवि उत्तरपश्चिम में बोरवेल द्वारा चरमोत्कर्ष पर पहुँच सकती है। और बाजार में दिया हुआ पैसा भी वापस नहीं आता.',
              VastuStrings.boreWell15 : 'एनएनडब्ल्यू में बोरवेल में व्यक्ति अपने जीवन साथी के साथ नहीं जुड़ सकता',
              VastuStrings.boreWell6 : 'उत्तर दिशा में बने बोरिंग कुओं के दर्शन से आपकी किस्मत चमक सकती है।',
              VastuStrings.mirror1 : 'एनएनई में मिररिंग करके अपनी प्रतिरक्षा प्रणाली को बढ़ावा दिया जा सकता है।',
              VastuStrings.mirror2 : 'पूर्वोत्तर में दर्पण की मदद से आपकी भविष्यवादी दृष्टि में सुधार किया जा सकता है।',
              VastuStrings.mirror3 : 'ईएनई में दर्पण का उपयोग करके आप घर में एक आनंदमय वातावरण बना सकते हैं।',
              VastuStrings.mirror4 : 'आपके जन प्रतिनिधित्व को पूर्व दिशा के दर्पण से गौरव प्राप्त होता है।',
              VastuStrings.mirror5 : 'ईएसई में दर्पणों की उपस्थिति भयभीत व्यवहार का कारण बन सकती है।',
              VastuStrings.mirror6 : 'एसई में दर्पण परिवार में आक्रामक व्यवहार को ट्रिगर करता है',
              VastuStrings.mirror7 : 'एसएसई में मिररिंग से असुरक्षित ड्राइविंग होने की संभावना है।',
              VastuStrings.mirror8 : 'दक्षिण दिशा में दर्पण होने से रक्त संबंधी रोग होते हैं',
              VastuStrings.mirror9 : 'एसएसडब्ल्यू में दर्पण द्वारा परिवार के असाधारण व्यवहार को प्रोत्साहित किया जाता है।',
              VastuStrings.mirror10 : 'एसडब्ल्यू में लगे शीशे के कारण अचानक दुर्घटना घटी।',
              VastuStrings.mirror11 : 'डब्ल्यूएसडब्ल्यू में प्रतिबिंबित होने पर अचानक वित्तीय नुकसान संभव है।',
              VastuStrings.mirror12 : 'पश्चिम में दर्पण स्वीकृत नहीं हैं।',
              VastuStrings.mirror13 : 'WNW में दर्पण द्वारा परिवार को दुख का सामना करना पड़ता है।',
              VastuStrings.mirror14 : 'यदि एनडब्ल्यू में दर्पण हो तो परिवार के सदस्य अपनी भावनाओं के प्रति अधिक संवेदनशील हो जाते हैं।',
              VastuStrings.mirror15 : 'एनएनडब्ल्यू में दर्पण की उपस्थिति से परिवार के सदस्यों की एक-दूसरे में अधिक रुचि हो जाती है।',
              VastuStrings.mirror16 : 'उत्तर दिशा में दर्पण होने से आपकी उन्नति होती है।',
              VastuStrings.waterTank1 : 'आपकी दवाइयों का असर कम हो जाता है. यदि आपका ओवरहेड टैंक उत्तर दिशा में है',
              VastuStrings.waterTank2 : 'एक लड़का स्वास्थ्य समस्याओं का सामना कर रहा है। यदि आपका ओवरहेड टैंक उत्तर-पूर्व दिशा में है',
              VastuStrings.waterTank3 : 'इस घर के पुरुष यात्रा पर जाने की योजना बनाते हैं, लेकिन वे सफल नहीं हो पाते हैं। यदि आपका ओवरहेड टैंक उत्तर दिशा में है',
              VastuStrings.waterTank4 : 'यदि आपका ओवरहेड टैंक पूर्व दिशा में है, तो परिवार में किसी को बुरे सपने आते हैं',
              VastuStrings.waterTank5 : 'यदि आपका ओवरहेड टैंक ईएसई दिशा में है। आपका विश्लेषणात्मक कौशल आपका कमजोर बिंदु बन जाता है।',
              VastuStrings.waterTank6 : 'यदि आपका ओवरहेड टैंक दक्षिण पूर्व दिशा में है। अपने स्टॉक का प्रबंधन करने में असमर्थ होने के परिणामस्वरूप आप एक अविश्वसनीय भागीदार बन सकते हैं।',
              VastuStrings.waterTank7 : 'यदि आपका ओवरहेड टैंक एसएसई दिशा में है। भ्रमित होना आपकी पहचान बन जाता है',
              VastuStrings.waterTank8 : 'ओवरहेड जल भंडारण टैंक के लिए दक्षिण दिशा अच्छी है जब तक कि टैंक का रंग सुनहरा या क्रीम न हो। इस दिशा में काले और नीले रंग से परहेज करें',
              VastuStrings.waterTank9 : 'एसएसडब्ल्यू दिशा ओवरहेड जल भंडारण टैंक के लिए अच्छी है जब तक कि टैंक का रंग सुनहरा या क्रीम न हो। इस दिशा में काले और नीले रंग से परहेज करें',
              VastuStrings.waterTank10 : 'दक्षिण पश्चिम दिशा में 225 डिग्री में ओवरहेड जल भंडारण टैंक का उपयोग न करें। यह 220 डिग्री या 230 डिग्री पर होना चाहिए. काले, नीले और हरे रंग से परहेज करें। गोल्डन या क्रीम का उपयोग करने का प्रयास करें',
              VastuStrings.waterTank11 : 'डब्ल्यूएसडब्ल्यू दिशा में ओवरहेड टैंक अच्छा धन और लाभ लाता है। काले, नीले और हरे रंग से परहेज करें। गोल्डन या क्रीम का उपयोग करने का प्रयास करें',
              VastuStrings.waterTank12 : 'पश्चिम दिशा में ओवरहेड जल भंडारण टैंक राजस्व के लिए बहुत उपयोगी है। काले, नीले और हरे रंग से परहेज करें। गोल्डन या क्रीम का उपयोग करने का प्रयास करें',
              VastuStrings.waterTank13 : 'डब्ल्यूएनडब्ल्यू में सफेद रंग का ओवरहेड जल भंडारण टैंक जीवन में हर पहलू में संतुलन लाता है। काले, नीले और हरे रंग से परहेज करें।',
              VastuStrings.waterTank14 : 'एनडब्ल्यू में ओवरहेड जल भंडारण टैंक केवल तभी अच्छा है जब एसडब्ल्यू एनडब्ल्यू टैंक से ऊपर हो, सुनिश्चित करें कि यह सफेद रंग का हो और हरे रंग से बचें',
              VastuStrings.waterTank15 : 'मनुष्य फिजूलखर्ची करने लगता है और ब्रांडेड चीजों को दिखाने के लिए अधिक पैसे खर्च करने लगता है। ख़र्चे नियंत्रण से बाहर हो जायेंगे। यदि आपका ओवरहेड टैंक NNW दिशा में है',
              VastuStrings.waterTank16: 'यदि आपका ओवरहेड टैंक उत्तर दिशा में है तो आपकी गणना कमजोर हो जाती है',
              VastuStrings.basement1: 'इस क्षेत्र में व्यक्ति अपने जीवन में स्वास्थ्य संबंधी समस्याओं से पीड़ित नहीं हो सकता है। और इस क्षेत्र में मानसिक शक्ति भी बढ़ती है।',
              VastuStrings.basement2: 'इस क्षेत्र में एकाग्रता शक्ति बढ़ेगी और मन में एक सफल विचार भी आएगा।',
              VastuStrings.basement3: 'इस क्षेत्र में परिवार छोटी-मोटी मौज-मस्ती करेगा और परिवार के सदस्य एक साथ रहेंगे।',
              VastuStrings.basement4: 'सरकारी क्षेत्र व्यक्ति के लिए सदैव मददगार रहेगा। तथा राजनीति से जुड़े सदस्यों से अच्छे संबंध बनाएं।',
              VastuStrings.basement5: 'इस क्षेत्र में व्यक्ति छोटी-छोटी बातों पर विवाद कर सकता है।',
              VastuStrings.basement6: 'इस क्षेत्र में व्यक्ति प्रेम संबंधी या बिजनेस पार्टनर संबंधी समस्याओं से पीड़ित रहेगा। तथा घर की महिलाएं छोटी-छोटी बातों पर उग्र हो जाएंगी।',
              VastuStrings.basement7: 'इस क्षेत्र में व्यक्ति के आत्मविश्वास में कमी आएगी और व्यक्ति अपने काम में आलस्य महसूस करेगा।',
              VastuStrings.basement8: 'इस क्षेत्र में लोग व्यक्तिगत छवि की समस्या से पीड़ित रहते हैं या घर के सगे भाई छोटी-छोटी बातों में झगड़ा कर देते हैं।',
              VastuStrings.basement9: 'व्यक्ति को घुटन महसूस होगी. और लोगों को धन हानि और समय की बर्बादी की भी समस्या होती है।',
              VastuStrings.basement10: 'व्यक्ति कौशल, सेवा, अनुभव, गुणवत्ता, उत्पादकता संबंधी मुद्दों से पीड़ित है। और परिवार के सदस्यों में स्वास्थ्य संबंधी समस्या भी बनती है।',
              VastuStrings.basement11: 'इस क्षेत्र में लोग शिक्षा संबंधी समस्याओं से पीड़ित हैं। और पैसे बचाने की भी समस्या का सामना करना पड़ता है।',
              VastuStrings.basement12: 'जातक को आत्मविश्लेषण की समस्या का सामना करना पड़ेगा।',
              VastuStrings.basement13: 'व्यक्ति अवसाद से ग्रस्त रहेगा। असफलताओं से सीखने का एक क्षेत्र है।',
              VastuStrings.basement14: 'इस क्षेत्र में व्यक्ति को कोर्ट-कचहरी के मामले तथा मानसिक तनाव अधिक रहेगा। और पेरोसन ने बाजार में पैसा भी ब्लॉक कर दिया।',
              VastuStrings.basement15: 'यह क्षेत्र अत्यधिक आकर्षण क्षेत्र के लिए है। और इस क्षेत्र के व्यक्ति को समझने में दिक्कत आती है।',
              VastuStrings.basement16: 'यह क्षेत्र बेसमेंट के लिए उपयुक्त है। इस क्षेत्र में व्यक्ति को धन कोष या आभूषण की प्राप्ति होती है।',
              VastuStrings.watch1: 'यह जोन सर्वोत्तम है। और व्यक्ति किसी लक्ष्य को समय पर संग्रहीत करने का लक्ष्य बनाता है।',
              VastuStrings.watch2: 'यह क्षेत्र नए बिजनेस विचार और रणनीति बनाने के लिए उपयुक्त है।',
              VastuStrings.watch3: 'जातक अपने व्यवसाय से आकर्षित होगा और अपने लक्ष्य पर फोकस भी करेगा।',
              VastuStrings.watch4: 'यह क्षेत्र राजनीति कनेक्शन जोड़ने के लिए बेहतर प्रभाव देता है। और व्यक्ति अपने समय का पाबंद हो जाता है।',
              VastuStrings.watch5: 'व्यक्ति व्यवसाय के बारे में गहन ज्ञान प्राप्त करेगा और व्यवसाय का नकारात्मक या सकारात्मक विश्लेषण भी करेगा।',
              VastuStrings.watch6: 'यह जोन उपयुक्त नहीं है. डर या संघर्ष को मुद्दा बनाएं।',
              VastuStrings.watch7: 'यह जोन उपयुक्त नहीं है. व्यक्ति को प्रेरणा, आत्मविश्वास या आराम क्षेत्र की कमी का सामना करना पड़ेगा।',
              VastuStrings.watch8: 'यह जोन उपयुक्त नहीं है. व्यक्ति विश्वास संबंधी समस्याओं से पीड़ित रहता है।',
              VastuStrings.watch9: 'यह क्षेत्र निगरानी के लिए उपयुक्त नहीं है. व्यक्ति को घुटन और मानसिक परेशानी महसूस होती है',
              VastuStrings.watch10: 'यह जोन उपयुक्त नहीं है. लोगों को बिना किसी कारण के उसके जीवन में अशांति का सामना करना पड़ेगा।',
              VastuStrings.watch11: 'यह जोन उपयुक्त नहीं है. व्यक्ति को शिक्षा संबंधी समस्याओं का सामना करना पड़ेगा और सहनशक्ति कमजोर हो जाएगी।',
              VastuStrings.watch12: 'यह उपयुक्त जोन नहीं है. इस क्षेत्र में व्यक्ति भावनात्मक या संवेदनशील होगा।',
              VastuStrings.watch13: 'यह क्षेत्र निगरानी के लिए उपयुक्त नहीं है. लोगों को नकारात्मक विचारों और भावनाओं का सामना करना पड़ता है।',
              VastuStrings.watch14: 'यह जोन उपयुक्त नहीं है. लोग उत्तर दिशा की दीवार पर घड़ी लटका सकते हैं।',
              VastuStrings.watch15: 'यह क्षेत्र निगरानी के लिए उपयुक्त नहीं है.',
              VastuStrings.watch16: 'यह क्षेत्र धन संबंधी कार्यों के लिए उपयुक्त है, व्यक्ति समय का बहुत पाबंद होकर यह कार्य करता है।',
              VastuStrings.studyTableLibrary1: 'यदि आप इस क्षेत्र में अध्ययन कर रहे हैं, तो आपका रुझान मेडिकल अध्ययन की ओर होगा। हेल्थ इंडस्ट्री से जुड़े स्टूडेंट के लिए यह जोन अच्छा है।',
              VastuStrings.studyTableLibrary2: 'स्टडी टेबल के लिए यह अच्छी जगह है. छात्र नए विचारों की कल्पना करेंगे और अपनी पढ़ाई में उत्कृष्टता प्राप्त करने के लिए आवश्यक अंतर्दृष्टि विकसित करेंगे। विशेषकर, शोध कार्य में।',
              VastuStrings.studyTableLibrary3: 'बच्चे पढ़ाई की बजाय खेल पर ध्यान देंगे। वे आमतौर पर अध्ययन के दौरान खेलने के लिए कुछ न कुछ चुनते हैं।',
              VastuStrings.studyTableLibrary4: 'विद्यार्थी राजनीति विज्ञान पढ़ना पसंद करेंगे।',
              VastuStrings.studyTableLibrary5: 'यहां पढ़ने वाला व्यक्ति अति विश्लेषणात्मक हो जाएगा और उसकी ग्रहण शक्ति प्रभावित होगी।',
              VastuStrings.studyTableLibrary6: 'कानून की पढ़ाई कर रहे लोगों के लिए अच्छा जोन है।',
              VastuStrings.studyTableLibrary7: 'यदि आप योग या खेल का अध्ययन करना चाहते हैं, या जिम प्रशिक्षक या योग शिक्षक बनना चाहते हैं तो यह आपके अध्ययन तालिका के लिए सही क्षेत्र है।',
              VastuStrings.studyTableLibrary8: 'बच्चे पढ़ाई में ध्यान नहीं लगा पाएंगे और पढ़ाई के दौरान उन्हें नींद आएगी।',
              VastuStrings.studyTableLibrary9: 'स्टडी टेबल के लिए अच्छा स्थान नहीं। बच्चे अपनी क्षमता के अनुसार बहुत कम अंक प्राप्त करेंगे।',
              VastuStrings.studyTableLibrary10: 'यदि आप कोई तकनीकी कौशल सीख रहे हैं तो अच्छा क्षेत्र है।',
              VastuStrings.studyTableLibrary11: 'स्कूली विद्यार्थियों के लिए यह सबसे अच्छा क्षेत्र है। यदि आप इस क्षेत्र में स्टडी टेबल रखने में सक्षम नहीं हैं तो इस क्षेत्र का लाभ उठाने के लिए कम से कम एक पेन स्टैंड अवश्य रखें।',
              VastuStrings.studyTableLibrary12: 'छात्र यहां बैठकर अपनी पढ़ाई में जो भी प्रयास करेंगे, उन्हें लाभ मिलेगा, खासकर अकाउंटेंसी की पढ़ाई के लिए।',
              VastuStrings.studyTableLibrary13: 'यहां इस स्टडी टेबल से बचना चाहिए।',
              VastuStrings.studyTableLibrary14: 'अगर आप स्टोरेज या इन्वेंट्री से संबंधित कुछ भी सीख रहे हैं तो यह आपके लिए एक अच्छा क्षेत्र है।',
              VastuStrings.studyTableLibrary15: 'बच्चों का ध्यान पढ़ाई में नहीं लगेगा, उनका रुझान ग्लैमर की ओर ज्यादा रहेगा।',
              VastuStrings.studyTableLibrary16: 'इस जोन में रखी स्टडी टेबल बच्चों को करियर ओरिएंटेड बनाएगी।',
              VastuStrings.medicineBox1: 'दवा रखने के लिए आदर्श क्षेत्र। यदि आप यहां दवा रखेंगे तो आपको शीघ्र परिणाम मिलेगा।',
              VastuStrings.medicineBox2: 'आप इस क्षेत्र का उपयोग दवाएँ रखने के लिए कर सकते हैं।',
              VastuStrings.medicineBox3: 'इस क्षेत्र का उपयोग दवाइयां रखने के लिए किया जा सकता है।',
              VastuStrings.medicineBox4: 'इस क्षेत्र में औषधियाँ रखी जा सकती हैं।',
              VastuStrings.medicineBox5: 'दवाइयाँ रखने के लिए अच्छा स्थान नहीं है।',
              VastuStrings.medicineBox6: 'जब कोई व्यक्ति दवा रखने के लिए दक्षिण पूर्व का उपयोग करता है तो उसे दवा का लाभ पाने के लिए अधिक दवा लेने की आवश्यकता होती है।',
              VastuStrings.medicineBox7: 'यदि दवाएं घर के इस क्षेत्र में रखी जाती हैं, तो निवासियों को फिट और स्वस्थ रहने के लिए उन्हें नियमित रूप से लेना होगा।',
              VastuStrings.medicineBox8: 'हर छोटी-छोटी समस्या के लिए दवा की जरूरत.',
              VastuStrings.medicineBox9: 'इस क्षेत्र में दवाओं के अप्रभावी हो जाने से उनकी बर्बादी होती है।',
              VastuStrings.medicineBox10: 'इस क्षेत्र में दवाइयां तो रखी जा सकती हैं लेकिन लोग लंबे समय तक दवाइयां नहीं ले सकते।',
              VastuStrings.medicineBox11: 'इस क्षेत्र में औषधियाँ भी रखी जा सकती हैं।',
              VastuStrings.medicineBox12: 'यह क्षेत्र दवाइयाँ रखने के लिए बहुत अच्छा है।',
              VastuStrings.medicineBox13: 'दवा रखने के लिए अच्छा क्षेत्र नहीं है',
              VastuStrings.medicineBox14: 'दवा से नियमित सहायता की आवश्यकता. इस क्षेत्र से बचें.',
              VastuStrings.medicineBox15: 'दवाइयाँ रखने के लिए यह एक अच्छा क्षेत्र है। जब उन्हें यहां रखा जाता है, तो वे निवासियों के लिए अच्छे उपचार प्रभाव उत्पन्न करते हैं।',
              VastuStrings.medicineBox16: 'दवा रखने के लिए अच्छा क्षेत्र.',
              VastuStrings.pets1: 'यह आपके पालतू जानवरों को रखने के लिए फिर से एक स्वीकार्य स्थान है।',
              VastuStrings.pets2: 'यह आपके पालतू जानवरों को रखने के लिए अच्छी जगह नहीं है। यह कम ऊर्जा और भावना का घर बनाता है।',
              VastuStrings.pets3: 'यह पालतू जानवरों के लिए एक अच्छा क्षेत्र है। वे स्वस्थ और ऊर्जावान बनते हैं।',
              VastuStrings.pets4: 'ईएनई के समान ही प्रभाव। अच्छी जगह।',
              VastuStrings.pets5: 'पालतू जानवरों पर कोई बुरा प्रभाव नहीं. उन्हें इस क्षेत्र में रखा जा सकता है.',
              VastuStrings.pets6: 'यह पालतू जानवरों के लिए अच्छा क्षेत्र नहीं है, यहां रहने से वे चिड़चिड़े हो जाते हैं।',
              VastuStrings.pets7: 'पालतू जानवरों को रखने के लिए यह आदर्श क्षेत्र है, वे यहां सतर्क और स्वस्थ रहते हैं।',
              VastuStrings.pets8: 'पालतू जानवरों को रखने के लिए यह एक अनुमत स्थान है।',
              VastuStrings.pets9: 'पालतू जानवर रखने के लिए इस क्षेत्र से बचें। उन्हें स्वास्थ्य संबंधी कारणों से कष्ट रहेगा।',
              VastuStrings.pets10: 'यह पालतू जानवरों के लिए एक अच्छी जगह है. वे आसानी से नए कौशल और आदेश सीख सकते हैं।',
              VastuStrings.pets11: 'आप अपने पालतू जानवरों को वेस्ट साउथ वेस्ट में रख सकते हैं।',
              VastuStrings.pets12: 'यह आपके पालतू जानवरों को रखने के लिए फिर से एक स्वीकार्य स्थान है।',
              VastuStrings.pets13: 'अपने पालतू जानवरों को यहां रखना ठीक नहीं है.',
              VastuStrings.pets14: 'आपके घर में इस क्षेत्र में पालतू जानवर रखे जा सकते हैं।',
              VastuStrings.pets15: 'पालतू जानवरों को रखने के लिए यह एक और अच्छा स्थान है। यहां ये आकर्षण का केंद्र बनते हैं.',
              VastuStrings.pets16: 'इस क्षेत्र में पालतू जानवर रखे जा सकते हैं।',
              VastuStrings.balcony1: 'माना जाता है कि एनएनई दिशा की ओर मुख वाली बालकनियों से स्वास्थ्य प्रतिरोधक क्षमता बढ़ती है।',
              VastuStrings.balcony2: 'यह दिशा जल तत्व से संबंधित है, और ऐसा माना जाता है कि उत्तर-पूर्व की ओर मुख करके व्यक्ति सकारात्मक ऊर्जा और आध्यात्मिक विकास को आकर्षित कर सकता है और मन की स्पष्टता भी प्राप्त कर सकता है।',
              VastuStrings.balcony3: 'यह क्षेत्र मौज-मस्ती और आनंद के लिए माना जाता है।',
              VastuStrings.balcony4: 'यह दिशा उगते सूरज से जुड़ी है, और ऐसा माना जाता है कि सुबह पूर्व दिशा की बालकनी पर समय बिताने से, व्यक्ति दिन भर के लिए सकारात्मक ऊर्जा को आकर्षित कर सकते हैं और एक सामाजिक नेटवर्क भी बना सकते हैं।',
              VastuStrings.balcony5: 'यह क्षेत्र बालकनियों के लिए ठीक नहीं है, इसलिए बालकनी को हरे या लाल पर्दे से ढक दें।',
              VastuStrings.balcony6: 'यह उपयुक्त नहीं है क्योंकि इस क्षेत्र में व्यक्ति क्रोध की समस्या से प्रभावित हो सकता है। बेहतर परिणाम के लिए इस क्षेत्र को लाल पर्दों से ढक दिया गया है।',
              VastuStrings.balcony7: 'यह क्षेत्र उपयुक्त नहीं है क्योंकि इस क्षेत्र में व्यक्ति क्रोध की समस्या से प्रभावित हो सकता है। बेहतर परिणाम के लिए इस क्षेत्र को लाल पर्दों से ढक दिया गया है।',
              VastuStrings.balcony8: 'ऐसा माना जाता है कि ये नकारात्मक ऊर्जा को आकर्षित करते हैं और रक्त संबंधी समस्याएं पैदा कर सकते हैं। बेहतर परिणाम के लिए इस क्षेत्र को लाल पर्दों से ढक दिया गया है।',
              VastuStrings.balcony9: 'इस दिशा में बनी बालकनी अत्यंत हानिकारक होती है। बेहतर परिणाम के लिए इस क्षेत्र को पीले पर्दों से ढक दिया गया है।',
              VastuStrings.balcony10: 'यह बालकनियों के लिए उपयुक्त क्षेत्र नहीं है, यह पिता और पुत्र के बीच बड़े झगड़े पैदा कर सकता है। इसलिए बेहतर परिणाम के लिए इसे पीले पर्दों से ढका जा सकता है।',
              VastuStrings.balcony11: 'यह क्षेत्र बालकनियों के लिए उपयुक्त नहीं है। बेहतर परिणाम के लिए इस क्षेत्र को सफेद या भूरे पर्दों से ढक दें।',
              VastuStrings.balcony12: 'बालकनियों के लिए यह खतरनाक क्षेत्र है। बेहतर परिणाम के लिए इस क्षेत्र को सफेद या भूरे पर्दों से ढका जा सकता है।',
              VastuStrings.balcony13: 'यह क्षेत्र एक अवसाद पैदा कर सकता है। बेहतर परिणाम के लिए इसे सफेद या भूरे पर्दों से ढका जा सकता है।',
              VastuStrings.balcony14: 'यह क्षेत्र उपयुक्त नहीं है क्योंकि यह क्षेत्र धन उधार समस्या के रूप में जाना जाता है। बेहतर परिणाम के लिए इस क्षेत्र को सफेद या भूरे पर्दों से ढका जा सकता है।',
              VastuStrings.balcony15: 'माना जाता है कि एनएनडब्ल्यू दिशा की ओर मुख वाली बालकनियाँ प्यार और आकर्षण को आकर्षित करती हैं।',
              VastuStrings.balcony16: 'यह दिशा धन के देवता कुबेर से जुड़ी है और ऐसा माना जाता है कि उत्तर दिशा की ओर मुख करके व्यक्ति सकारात्मक ऊर्जा और वित्तीय प्रचुरता को आकर्षित कर सकते हैं।',
              VastuStrings.electricMeter1 :'अच्छा नहीं, यह स्वास्थ्य इम्यूनिटी को परेशान कर सकता है।',
              VastuStrings.electricMeter2 :'यह क्षेत्र लघु मस्तिष्क समस्याओं का कारण बन सकता है।',
              VastuStrings.electricMeter3 :'यह क्षेत्र बहुत हानिकारक है।',
              VastuStrings.electricMeter4 :'यह क्षेत्र इलेक्ट्रिक मीटर्स के लिए उपयुक्त है।',
              VastuStrings.electricMeter5 :'यह क्षेत्र इलेक्ट्रिक मीटर्स के लिए उपयुक्त है।',
