              VastuStrings.homeTreatment30: 'स्थायी: लोहे के पट्टों के साथ ब्लॉक, अस्थायी: सफेद टेप के साथ ब्लॉक',
              VastuStrings.homeTreatment31: 'स्थायी: एल्युमिनियम पट्टियों के साथ ब्लॉक, अस्थायी: नीली टेप के साथ ब्लॉक',
              VastuStrings.homeTreatment32: 'स्थायी: एल्युमिनियम पट्टियों के साथ ब्लॉक, अस्थायी: नीली टेप के साथ ब्लॉक',
              VastuStrings.kitchenTreatment1: '1. चुल्हे के नीचे हरी टेप। \n2. हरी रसोई ऊर्जा।',
              VastuStrings.kitchenTreatment2: 'संतुलन बनाने की कोई आवश्यकता नहीं है, लेकिन अगर पैसे से संबंधित अत्यधिक सोच का सामना करना पड़ रहा है तो स्टोव को एसएसई में स्थानांतरित कर सकते हैं। नीले/काले ग्रेनाइट का प्रयोग न करें। यदि उपयोग करें तो चूल्हे के नीचे पीले रंग का टेप लगा सकते हैं।',
              VastuStrings.kitchenTreatment3: 'नीले/काले ग्रेनाइट का उपयोग न करें। अगर किया जाए तो आप चुल्हे के नीचे पीले रंग का टेप लगा सकते हैं।',
              VastuStrings.kitchenTreatment4: '1. चुल्हे के नीचे पीला टेप। \n2. पीली रसोई ऊर्जा।',
              VastuStrings.kitchenTreatment5: '1. चुल्हे के नीचे हरी टेप। \n2. हरी रसोई ऊर्जा।',
              VastuStrings.bedRoomTreatment1: 'नीला/पिस्ता रंग अनुमत है। लाल/पीला से बचें। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment2: 'नीला/स्काईब्लू/पिस्ता अनुमत है। लाल/पीला से बचें। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment3: 'संतुलित होना चाहिए। विरोधी रंगों को हटाया जाना चाहिए। हरा, भूरा, क्रीम, आसमानी नीला उपयोग किया जा सकता है। लाल, गुलाबी, बैंगनी, गहरा पीला, सफेद और स्लेटी ना कहें। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment4: 'बेडरूम के लिए अच्छा क्षेत्र। पीला या लाल रंग से बचें। और हरा या पिस्ता इस क्षेत्र में सबसे अच्छा रंग है। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment5: 'नीला या क्रीम रंग से बचें। इस क्षेत्र में हरा या पिस्ता रंग का उपयोग करें \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment6: 'लाल / गुलाबी / बैंगनी / बैंगनी और क्रीम के संतुलित होना चाहिए (नीला / काला, सफेद और स्लेटी का उपयोग करने से बचें) \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment7: 'बेडरूम के लिए अच्छा क्षेत्र। गुलाबी / बैंगनी / क्रीम रंग का उपयोग करें। सफेद / नीला रंग से बचें \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment8: 'बेडरूम के लिए अच्छा क्षेत्र। गुलाबी / बैंगनी / लाल रंग का उपयोग करें। काला / सफेद रंग से बचें। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment9: 'सख्ती से बचें। क्रीम / पीला रंग का उपयोग करें। और बाकी सभी रंग से बचें। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment10: 'पीला रंग और क्रीम, थोड़ा सा सफेद उपयोग किया जा सकता है। नीला, काला, हरा, भूरा और लाल से बचें। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment11: 'सफेद / धूसर, क्रीम, हल्का पीला, हल्का नीला। पानी के काले शेडों, हरा, भूरा और लाल से बचें \n1। संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment12: 'हरा या नीला रंग से बचें। अधिक ग्रे / क्रीम / हल्का पीला उपयोग करें \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment13: 'बेडरूम के लिए अच्छा क्षेत्र। सफेद / ग्रे रंग का उपयोग करें। बाकी सभी रंगों से बचें। \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment14: 'सफेद / ग्रे रंग का उपयोग करें। बाकी सभी रंग से बचें \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment15: 'सफेद / ग्रे, क्रीम, हल्का पीला, हल्का नीला उपयोग करें। पानी के काले शेडों, हरा, भूरा, लाल से बचें। संबंध में प्रेम को बढ़ाने के लिए \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.bedRoomTreatment16: 'नीला / काला / क्रीम और हल्का हरा अनुमत है। लाल / पीला से बचें। वित्तीय रूप से मजबूत बनाने के लिए \n1 संपूर्ण डिस्क का उपयोग करें।',
              VastuStrings.toiletSepticTankTreatment1: '1 नीला टेप \n2 एल्युमिनियम स्ट्रिप \n3 नीला नहाने का सिंकर \n4 नीली दीवारी बैंड',
              VastuStrings.toiletSepticTankTreatment2: '1 हरा टेप \n2 स्टेनलेस स्टील स्ट्रिप \n3 हरा नहाने का सिंकर \n4 हरी दीवारी बैंड',
              VastuStrings.toiletSepticTankTreatment3: 'कोई उपचार की आवश्यकता नहीं है।',
              VastuStrings.toiletSepticTankTreatment4: '1 लाल टेप \n2 तांबे की स्ट्रिप \n3 लाल नहाने का सिंकर \n4 लाल दीवारी बैंड।',
              VastuStrings.toiletSepticTankTreatment5: 'कोई उपचार की आवश्यकता नहीं है।',
              VastuStrings.toiletSepticTankTreatment6: '1. पीला टेप \n2. ब्रास स्ट्रिप \n3. पीला नहाने का सिंकर \n4. पीली दीवारी बैंड',
              VastuStrings.toiletSepticTankTreatment7: '1. सफेद टेप \n2. लोहे की स्ट्रिप \n3. सफेद दीवारी बैंड \n4. सफेद नहाने का सिंकर',
              VastuStrings.toiletSepticTankTreatment8: 'कोई उपचार की आवश्यकता नहीं है।',
              VastuStrings.toiletSepticTankTreatment9: '1. सफेद टेप \n2. लोहे की स्ट्रिप \n3. सफेद नहाने का सिंकर \n4. सफेद दीवारी बैंड',
              VastuStrings.toiletSepticTankTreatment10: '1 नीला टेप \n2 एल्युमिनियम स्ट्रिप \n3 नीला नहाने का सिंकर \n4 नीली दीवारी बैंड',
              VastuStrings.dustbinTreatment1 : 'यदि कोई विकल्प नहीं है, तो केवल नीला कूड़ादान रखें।',
              VastuStrings.dustbinTreatment2 : 'बिल्कुल भी सिफारिश नहीं की जाती',
              VastuStrings.dustbinTreatment3 : 'यदि कोई विकल्प नहीं है, तो केवल हरा कूड़ादान रखें।',
              VastuStrings.dustbinTreatment4 : 'केवल लाल या हरा रंग।',
              VastuStrings.dustbinTreatment5 : 'यदि कोई विकल्प नहीं है, तो केवल लाल कूड़ादान रखें।',
              VastuStrings.dustbinTreatment6 : 'केवल पीला या क्रीम',
              VastuStrings.dustbinTreatment7 : 'एक बड़ा नहीं',
              VastuStrings.dustbinTreatment8 : 'नहीं',
              VastuStrings.dustbinTreatment9 : 'धूसर या सफेद रंग।',
              VastuStrings.dustbinTreatment10 : 'केवल सफेद या क्रीम',
              VastuStrings.dustbinTreatment11 : 'यदि कोई विकल्प नहीं है, तो केवल सफेद कूड़ादान रखें।',
              VastuStrings.dustbinTreatment12 : 'यदि कोई विकल्प नहीं है, तो केवल नीला कूड़ादान रखें।',
              VastuStrings.staircaseTreatment1 : '1 हरित सीढ़ी ऊर्जा का प्रयोग करें।',
              VastuStrings.staircaseTreatment2 : '1 लाल सीढ़ी ऊर्जा का प्रयोग करें।',
              VastuStrings.staircaseTreatment3 : '1 नीली सीढ़ी ऊर्जा का प्रयोग करें।',
              VastuStrings.staircaseTreatment4 : '1 सफेद सीढ़ी ऊर्जा का प्रयोग करें।',
              VastuStrings.storeRoomTreatment1: '1 नीली लाइट का प्रयोग करें। \n2 जल तत्व चैंटिंग मशीन का प्रयोग करें। \n3 नीला पिरामिड (4”).',
              VastuStrings.storeRoomTreatment2: '1 नीली बल्ब को बढ़ावा दें। \n2 जल तत्व चैंटिंग मशीन का प्रयोग करें। \n3 नीला पिरामिड (4”).',
              VastuStrings.storeRoomTreatment3: '1 हरे बल्ब का प्रयोग करें। \n2 वायु तत्व चैंटिंग मशीन का प्रयोग करें। \n3 हरा पिरामिड (4”).',
              VastuStrings.storeRoomTreatment4: '1 लाल बल्ब का प्रयोग करें \n2 अग्नि तत्व चैंटिंग मशीन का प्रयोग करें। \n3 लाल पिरामिड (4”).',
              VastuStrings.storeRoomTreatment5: 'आत्मविश्वास बढ़ाने के लिए \n1 लाल लाइट का प्रयोग करें। \n2 अग्नि तत्व चैंटिंग मशीन का प्रयोग करें। \n3 लाल पिरामिड (4”).',
              VastuStrings.storeRoomTreatment6: 'नाम और आराम बढ़ाने के लिए \n1 लाल लाइट का प्रयोग करें। \n2 अग्नि तत्व चैंटिंग मशीन का प्रयोग करें। \n3 लाल पिरामिड (4”).',
              VastuStrings.storeRoomTreatment7: '1 पीली लाइट का प्रयोग करें। \n2 पृथ्वी तत्व चैंटिंग मशीन का प्रयोग करें। \n3 पीला पिरामिड (4”).',
              VastuStrings.storeRoomTreatment8: 'कौशल बढ़ाने और सर्वोत्तम संबंध बनाने के लिए। \n1 पीली लाइट का प्रयोग करें। \n2 पृथ्वी तत्व चैंटिंग मशीन का प्रयोग करें। \n3 पीला पिरामिड (4”).',
              VastuStrings.storeRoomTreatment9: '1 सफेद लाइट का प्रयोग करें। \n2 अंतरिक्ष तत्व चैंटिंग मशीन का प्रयोग करें। \n3 सफेद पिरामिड (4”).',
              VastuStrings.storeRoomTreatment10: 'डिप्रेशन से उपचार के लिए \n1 सफेद लाइट का प्रयोग करें। \n2 अंतरिक्ष तत्व चैंटिंग मशीन का प्रयोग करें। \n3 सफेद पिरामिड (4”).',
              VastuStrings.storeRoomTreatment11: 'सामाजिक सहारा बढ़ाने या स्थिरता के लिए। \n1 सफेद लाइट का प्रयोग करें। \n2 अंतरिक्ष तत्व चैंटिंग मशीन का प्रयोग करें। \n3 सफेद पिरामिड (4”).',
              VastuStrings.storeRoomTreatment12: '1 नीली लाइट का प्रयोग करें \n2 जल तत्व चैंटिंग मशीन का प्रयोग करें। \n3',
              VastuStrings.boreWellTreatment1: '1 सम्पूर्ण शिफ्टर का प्रयोग करें।',
              VastuStrings.waterTankTreatment1: '1 विधि शूल उत्पाद का उपयोग करें, और उत्पाद को पश्चिम दिशा में लटकाएं।',
              VastuStrings.basementTreatment1: '1 सीढ़ी पर पहला कदम, काटने के लिए हरे रंग के टेप का उपयोग करें। \n2 एसएस स्ट्रिप का प्रयोग करें। \n3 हरे दीवार बैंड का प्रयोग करें। \n4 संपूर्ण एलिवेटर का उपयोग करें।',
              VastuStrings.basementTreatment2: '1. सीढ़ी पर पहला कदम, काटने के लिए लाल रंग के टेप का उपयोग करें। \n2 तांबे की पट्टी का प्रयोग करें। \n3 लाल दीवार बैंड का प्रयोग करें। \n4 संपूर्ण एलिवेटर का उपयोग करें',
              VastuStrings.basementTreatment3: '1. सीढ़ी पर पहला कदम, काटने के लिए लाल रंग के टेप का उपयोग करें। \n2 तांबे की पट्टी का प्रयोग करें। \n3 लाल दीवार बैंड का प्रयोग करें। \n4 संपूर्ण एलिवेटर का उपयोग करें।',
              VastuStrings.basementTreatment4: '1 सीढ़ी पर पहला कदम, काटने के लिए पीले रंग के टेप का उपयोग करें। \n2 पीतल धातु का प्रयोग करें। \n3 पीले दीवार बैंड का प्रयोग करें। \n4 संपूर्ण एलिवेटर का उपयोग करें।',
              VastuStrings.basementTreatment5: '1 सीढ़ी पर पहला कदम, काटने के लिए सफेद रंग के टेप का उपयोग करें। \n2 लौह धातु का प्रयोग करें। \n3 सफेद दीवार बैंड का प्रयोग करें। \n4 संपूर्ण एलिवेटर का उपयोग करें।',
              VastuStrings.basementTreatment6: '1. सीढ़ी पर पहला कदम, काटने के लिए सफेद रंग के टेप का उपयोग करें। \n2 लौह धातु का प्रयोग करें। \n3 सफेद रंग के बैंड का प्रयोग करें। \n4 संपूर्ण एलिवेटर का उपयोग करें।',
              VastuStrings.basementTreatment7: '1 सीढ़ी पर पहला कदम, नीले रंग के टेप का प्रयोग करें। \n2 लौह धातु का प्रयोग करें। \n3 नीले वॉल बैंड का प्रयोग करें। \n4 संपूर्ण एलिवेटर का उपयोग करें।',
              VastuStrings.basementTreatment8: '1. सीढ़ी पर पहला कदम रखते हुए नीले रंग के टेप का प्रयोग करें। \n2 एल्युमीनियम धातु का प्रयोग करें। \n3 नीले वॉल बैंड का उपयोग करें \n4 संपूर्ण एलिवेटर का उपयोग करें।',
              VastuStrings.noTreatmentAvailable: 'कोई उपचार उपलब्ध नहीं है.',
              VastuStrings.officeVastuZones: 'कार्यालय वास्तु क्षेत्र',
              VastuStrings.accountDepartment: 'खाता विभाग',
              VastuStrings.basementOffice: 'बेसमेंट कार्यालय',
              VastuStrings.computerTable: 'कम्प्युटर की मेज़',
              VastuStrings.ceoRoom: 'सीईओ कक्ष',
              VastuStrings.marketingDepartment: 'व्यापार विभाग',
              VastuStrings.entranceMainDoor: 'प्रवेश/मुख्य द्वार',
              VastuStrings.drinkingWater: 'पेय जल',
              VastuStrings.purchaseDepartment: 'खरीद विभाग',
              VastuStrings.rndDepartment: 'आरएनडी विभाग',
              VastuStrings.officeReception: 'कार्यालय रिसेप्शन',
              VastuStrings.waitingRoom: 'प्रतीक्षालय',
              VastuStrings.washroomOffice: 'शौचालय कार्यालय',
              VastuStrings.dustbinOffice: 'कूड़ेदान कार्यालय',
              VastuStrings.weightMachine: 'वजन मशीन',

              VastuStrings.accountDepartment1: 'अधिक संग्रह को उत्तर-पूर्व क्षेत्र में लेने की गई मदद लेखा विभाग द्वारा मिल सकती है।',
              VastuStrings.accountDepartment2: 'उत्तर-पूर्व क्षेत्र में लेखा विभाग आलसीता का स्रोत हो सकता है।',
              VastuStrings.accountDepartment3: 'पूर्व-उत्तर प्रदेश क्षेत्र में विपरीत लिंगों का होना उत्पादकता में निष्पादक होगा।',
              VastuStrings.accountDepartment4: 'पूर्व क्षेत्र के लेखा विभाग में अच्छा काम है, लेकिन प्रबंधक के साथ संघर्ष है।',
              VastuStrings.accountDepartment5: 'पूर्व-दक्षिण-पूर्व क्षेत्र में लेखा विभाग का अच्छा काम है, लेकिन यह हमेशा भ्रांतिपूर्ण होता है।',
              VastuStrings.accountDepartment6: 'यदि लेखा विभाग मौजूद है, तो दक्षिण-पूर्व क्षेत्र दैनिक आय कंपनियों के लिए उपयुक्त है।',
              VastuStrings.accountDepartment7: 'उत्तर-दक्षिण-पूर्व क्षेत्र में लेखा विभाग के सर्वोत्तम परिणाम होते हैं, जो सर्वोत्तम क्षेत्र है।',
              VastuStrings.accountDepartment8: 'दक्षिण क्षेत्र लेखा विभाग के लिए आदर्श है और कंपनियों के लिए सफलता के लिए ले जा सकता है।',
              VastuStrings.accountDepartment9: 'SSW क्षेत्र में उसकी प्रयोग एकाधिक नेतृत्व के कारण नुकसान की प्रत्याशा है।',
              VastuStrings.accountDepartment10: 'लेखा विभाग के लिए पश्चिम-दक्षिण-पश्चिम क्षेत्र लाभकारी है क्योंकि इससे इसके कर्मचारियों के कौशल में सुधार होगा।',
              VastuStrings.accountDepartment11: 'WSW क्षेत्र में लेखा विभाग उसके स्वभाव के कारण अधिक बचत करने में मदद करता है।',
              VastuStrings.accountDepartment12: 'पश्चिम क्षेत्र में लेखा विभाग की प्रकृति आपको अधिक लाभ प्राप्त करने की अनुमति देती है।',
              VastuStrings.accountDepartment13: 'पश्चिम-उत्तर-पश्चिम क्षेत्र में उनकी प्रकृति कारण से लेखा विभाग आपको नुकसान में ले जाता है।',
              VastuStrings.accountDepartment14: 'लेखा विभाग उत्तर पश्चिम क्षेत्र में। कर्मचारियों की नौकरी छोड़ने का जोखिम उनके संवेदनशीलता को बढ़ाता है।',
              VastuStrings.accountDepartment15: 'लेखा विभाग उत्तर-उत्तर पश्चिम क्षेत्र में। कर्मचारी प्रेम संबंधों में प्रवृत्त होंगे और अपने काम को ध्यान नहीं देंगे।',
              VastuStrings.accountDepartment16: 'उत्तर क्षेत्र में लेखा विभाग द्वारा अधिक संचय करना आसान बनाया जा सकता है।',
              VastuStrings.basementOffice1: 'उत्तरी क्षेत्र में एक बेसमेंट होना आपके स्वास्थ्य और धन में बढ़ी हुई सुधार के लिए ले जा सकता है।',
              VastuStrings.basementOffice2: 'उत्तर-पूर्व क्षेत्र की बेसमेंट में आपके स्वस्थ जीवनशैली को बढ़ावा देने की संभावना है।',
              VastuStrings.basementOffice3: 'आध्यात्मिक रूप से जुड़ना और काम पर ध्यान केंद्रित करना उत्तर-पूर्व क्षेत्र में स्थित बेसमेंट में प्राप्त किया जा सकता है।',
              VastuStrings.basementOffice4: 'खुशहाल जीवनशैली और काम में आनंद लेने के लिए, पूर्व-उत्तर-पूर्व क्षेत्र में स्थित बेसमेंट आपकी मदद कर सकता है।',
              VastuStrings.basementOffice5: 'सरकारी लाभ प्राप्त करने के लिए पूर्व क्षेत्र में स्थित बेसमेंट मदद कर सकता है। परिवार के मुखिया में हमेशा हिंसा मौजूद रहेगी।',
              VastuStrings.basementOffice6: 'पूर्व-दक्षिण-पूर्व में बेसमेंट आपकी गिरावट शुरू कर देगा। चिंता हमेशा अपने उच्चतम स्तर पर होगी।',
              VastuStrings.basementOffice7: 'दक्षिण-पूर्व इलाके में स्थित बेसमेंट के पास महिला स्वास्थ्य समस्याएं और गर्भपात का कारण बन सकता है।',
              VastuStrings.basementOffice8: 'दक्षिण-दक्षिण-पूर्व क्षेत्र में स्थित बेसमेंट आपकी शक्ति और आत्मविश्वास को कमजोर कर सकता है।',
              VastuStrings.basementOffice9: 'दक्षिण क्षेत्र में बेसमेंट आपको रक्त समस्याओं और वित्तीय समस्याओं में ले जाएगा।',
              VastuStrings.basementOffice10: 'दक्षिण-पश्चिम क्षेत्र में बेसमेंट होने पर घाते और दुर्घटनाएं हो सकती हैं।',
              VastuStrings.basementOffice11: 'पश्चिम-दक्षिण क्षेत्र में स्थित बेसमेंट लकवा जैसी मुख्य स्वास्थ्य समस्याओं का कारण बनेगा।',
              VastuStrings.basementOffice12: 'पश्चिम-दक्षिण-पश्चिम क्षेत्र में स्थित बेसमेंट बचत को व्यवधान करेगा।',
              VastuStrings.basementOffice13: 'पश्चिम क्षेत्र में स्थित बेसमेंट आपको औसत परिणाम देगा लेकिन आपको पहले संतुलन बनाना होगा।',
              VastuStrings.basementOffice14: 'पश्चिम-उत्तर-पश्चिम क्षेत्र में स्थित बेसमेंट आपके दिमाग को उत्तेजित करेगा और आपको सुन्न कर देगा।',
              VastuStrings.basementOffice15: 'पश्चिम-उत्तर क्षेत्र में स्थित बेसमेंट आपको कर्ज की समस्याओं का सामना करवा सकता है और बाजार से पैसे वापस नहीं मिलेंगे।',
              VastuStrings.basementOffice16: 'उत्तर-पश्चिम-पश्चिम क्षेत्र में स्थित बेसमेंट में औसत परिणाम प्राप्त किए जा सकते हैं। अवसर उत्पन्न होंगे। यदि उत्तर क्षेत्र शामिल किया जाता है, तो आप इससे पैसे कमा सकते हैं।',
              VastuStrings.computerTable1: 'अगर आपका कंप्यूटर उत्तर-पूर्व-पूर्व क्षेत्र में स्थित है, तो यह आपको स्वस्थ जीवनशैली की ओर ले जाएगा।',
              VastuStrings.computerTable2: 'अगर आपका कंप्यूटर पूर्व-पूर्व क्षेत्र में स्थित है, तो आप आध्यात्मिकता की खोज करेंगे और आध्यात्मिक गतिविधियों में अधिक सक्रिय होंगे।',
              VastuStrings.computerTable3: 'अगर आपका कंप्यूटर पूर्व-पूर्व-पूर्व क्षेत्र में स्थित है, तो आप इससे फिल्में और टीवी शो देखेंगे और इससे आनंद लेंगे।',
              VastuStrings.computerTable4: 'अगर आपका कंप्यूटर पूर्व क्षेत्र में स्थित है, तो आप सरकारी नौकरियों और सरकारी ठेकों की खोज करेंगे और इससे पैसे कमाएंगे।',
              VastuStrings.computerTable5: 'अगर आपका कंप्यूटर पूर्व-दक्षिण-पूर्व क्षेत्र में स्थित है, तो आप गहरी जानकारी की खोज करेंगे और धीरे-धीरे एक शोधकर्ता बनेंगे।',
              VastuStrings.computerTable6: 'सी ई क्षेत्र में कंप्यूटर के साथ ब्रांडेड कपड़ों की शॉपिंग ऑनलाइन संभव है।',
              VastuStrings.computerTable7: 'यदि आपका कंप्यूटर दक्षिण-पूर्व-पूर्व क्षेत्र में है, तो शारीरिक गतिविधि और बल प्रशिक्षण की खोज संभव है।',
              VastuStrings.computerTable8: 'दक्षिण क्षेत्र में कंप्यूटर आपको आराम करने में मदद करेगा और आप लंबे समय तक काम करेंगे।',
              VastuStrings.computerTable9: 'कंप्यूटर एसएसडब्ल्यू क्षेत्र में आपको काम करने नहीं देगा। आपके कंप्यूटर पर जो कुछ भी करते हैं, वह कठिन होगा और समय की बर्बादी होगी।',
              VastuStrings.computerTable10: 'एस डब्ल्यू क्षेत्र में कंप्यूटर आपको अपने काम में अधिक कौशल प्राप्त करने में मदद करेगा। ऑनलाइन प्रतिस्पर्धात्मक खेलों के लिए अच्छा है।',
              VastuStrings.computerTable11: 'डब्ल्यू एस डब्ल्यू क्षेत्र में कंप्यूटर आपको अच्छे शैक्षिक लक्ष्य प्राप्त करने में मदद करेगा और शेयर मार्केट में आपकी मदद करेगा।',
              VastuStrings.computerTable12: 'पश्चिम क्षेत्र में कंप्यूटर आपको लाभ प्राप्त करने में मदद करेगा और व्यापार और शिक्षा में बहुत सहायक होगा, आपको इसका उपयोग करते समय पूर्व दिशा को सामना करना चाहिए।',
              VastuStrings.computerTable13: 'पश्चिम-उत्तर-पश्चिम क्षेत्र में कंप्यूटर का उपयोग करने से घाटे होंगे और आप अवसाद महसूस करेंगे।',
              VastuStrings.computerTable14: 'उत्तर-पश्चिम क्षेत्र में कंप्यूटर कर्मचारियों को अस्थिर बना देगा और वित्तीय प्रबंधन के लिए बहुत खराब क्षेत्र है।',
              VastuStrings.computerTable15: 'उत्तर-उत्तर-पश्चिम क्षेत्र में कंप्यूटर केवल एक लिंग के लिए अच्छा है; यदि कई लिंग जोड़े जाते हैं, तो वे उत्पादक नहीं होंगे और व्यवसाय के लिए अच्छे नहीं होंगे।',
              VastuStrings.computerTable16: 'यदि आपका कंप्यूटर उत्तर क्षेत्र में स्थित है, तो इससे पैसे कमाना संभव है।',
              VastuStrings.ceoRoom1: 'NNE क्षेत्र में कंपनी के मुख्य कार्यालय में कंप्यूटर लाभकारी होते हैं, क्योंकि वे लोगों के स्वास्थ्य को सुधारते हैं और एक स्वस्थ मन कार्यक्षमता में नेतृत्व करता है।',
              VastuStrings.ceoRoom2: 'मुख्य कार्यालय उत्तर पूर्वी क्षेत्र में स्थित है, जो वित्तीय प्रबंधन के लिए अच्छा नहीं है, और यह आलस्य और गैर-उत्पादक व्यवहार के लिए आगे बढ़ सकता है।',
              VastuStrings.ceoRoom3: 'ENE में मुख्य कार्यालय सबसे अच्छा विकल्प नहीं है क्योंकि यह अत्यधिक यात्रा के कारण उत्पादकता में कमी का कारण बनता है।',
              VastuStrings.ceoRoom4: 'पूर्व दिशा में स्थित मुख्य कार्यालय लाभकारी है क्योंकि यह आपको सरकारी लाभ प्राप्त करने में सहायक होगा, और सरकारी ठेकेदारों की संख्या बढ़ जाएगी।',
              VastuStrings.ceoRoom5: 'ESE क्षेत्र में मुख्य कार्यालय अच्छा नहीं है। व्यक्ति गहरी चिंता और विश्लेषणात्मक हो जाता है, जिससे उनके निर्णय में देरी होती है और वे कम उत्पादक बनते हैं।',
              VastuStrings.ceoRoom6: 'SE में मुख्य कार्यालय लाभकारी है क्योंकि यह अधिक वित्तीय कमाई लाता है, लेकिन यह क्रोध के खर्च में आता है।',
              VastuStrings.ceoRoom7: 'SSE क्षेत्र में मुख्य कार्यालय उपचार विभाग के लिए आदर्श क्षेत्र है। यह आपको जल्दी उपचार मिलने और अधिक वित्तीय लाभ प्राप्त करने में मदद करता है।',
              VastuStrings.ceoRoom8: 'दक्षिण क्षेत्र में CEO केबिन अच्छा है। व्यक्ति यहां प्रबंधन में बहुत अच्छा हो जाता है और अधिक लाभकारी होता है।',
              VastuStrings.ceoRoom9: 'SSW में CEO केबिन लाभकारी नहीं है, इसलिए प्रमुख घाते आपकी पहचान बन रहे हैं।',
              VastuStrings.ceoRoom10: 'स्व जोन में CEO केबिन आदर्श है क्योंकि यहां व्यक्ति कंपनी के लिए सर्वश्रेष्ठ निर्णय लेता है। जो कंपनी के लिए एक बेहतर भविष्य की ओर ले जाता है।',
              VastuStrings.ceoRoom11: 'WSW में मुख्य कार्यालय आपके कंपनी की लाभकारिता और कोई भी नुकसान के शून्य संभावना सुनिश्चित करता है। टेबल के लिए ग्रे रंग की सिफारिश की जाती है।',
              VastuStrings.ceoRoom12: 'पश्चिम मुख्य कार्यालय के लिए अच्छा है, व्यक्ति यहां अधिक स्थिर हो जाता है और भविष्य के निर्णय लेता है जो लाभकारी होते हैं।',
              VastuStrings.ceoRoom13: 'WNW में CEO केबिन अनुचित नहीं है, यहां उन्हें अच्छे निर्णय नहीं ले सकते जो उन्हें अवसाद में डालते हैं।',
              VastuStrings.ceoRoom14: 'NW केवल उत्तर-पश्चिम दिशा के लिए अच्छा है यदि कंपनी यात्रा, जल और दूध उत्पादों से संबंधित है अन्यथा कंपनी दिवालिया हो जाएगी।',
              VastuStrings.ceoRoom15: 'NNW में मुख्य कार्यालय अच्छा है। व्यक्ति यहां कारिश्माई होता है। कर्मचारी उससे सलाह लेना पसंद करेंगे।',
              VastuStrings.ceoRoom16: 'उत्तर क्षेत्र में स्थित मुख्य कार्यालय, वित्तीय और बैंकिंग प्रशासन के लिए लाभदायक है।',
              VastuStrings.marketingDepartment1: 'NNE में मार्केटिंग माध्यम है। यहां के लोग फ़ील्ड काम के लिए नहीं जा सकते लेकिन अच्छे फ़ोन कॉल और पेपरवर्क को संभाल सकते हैं।',
              VastuStrings.marketingDepartment2: 'पूर्व में विपणन जोन में अच्छा नहीं है, यहां के लोग आलसी और उपद्रवी हो जाते हैं और वे कड़ी मेहनत करना नहीं चाहते।',
              VastuStrings.marketingDepartment3: 'ENE क्षेत्र में विपणन लोग अधिक मज़े करते हैं और फ़ील्ड काम करने का आनंद लेते हैं, उलटा लिंग के लिए अनुकूल नहीं है।',
              VastuStrings.marketingDepartment4: 'पूर्व जोन विपणन विभाग के लिए आदर्श क्षेत्र है, कर्मचारी यहां उच्च समाज के लोगों के साथ अच्छे संबंध बनाते हैं और इससे लाभ कमाते हैं।',
              VastuStrings.marketingDepartment5: 'पूर्व-दक्षिण में विपणन विभाग के लिए अच्छा नहीं है, यहां के कर्मचारी चिंतित और विश्लेषणात्मक हो जाते हैं। वे शोधकर्ता बन जाएँगे और विपणन पर ध्यान नहीं दे पाएंगे।',
              VastuStrings.marketingDepartment6: 'दक्षिण-पूर्व क्षेत्र विपणन कर्मचारियों के लिए अच्छा है क्योंकि वे लोगों को अपने उत्पाद को पसंद करने के लिए अद्भुत क्षमताओं के साथ आत्मविश्वास और लाभ की ओर ले जाते हैं।',
              VastuStrings.marketingDepartment7: 'SSE क्षेत्र में विपणन फ़ील्ड काम करने वालों के लिए अप्रतिम क्षेत्र है। यहां आपकी आत्मविश्वास की क्षमता को सुधारने में मदद मिलती है जो लाभ के लिए उत्पन्न होती है।',
              VastuStrings.marketingDepartment8: 'दक्षिण क्षेत्र विपणन विभाग के लिए अच्छा है। यहां के कर्मचारी ध्यान और बहुत ही औपचारिक तरीके से काम करते हैं।',
              VastuStrings.marketingDepartment9: 'SSW में विपणन विभाग के लिए अच्छा स्थान नहीं है, यहां का काम समय और पैसे की बर्बादी हो जाएगी।',
              VastuStrings.marketingDepartment10: 'दक्षिण पश्चिम में विपणन विभाग के लिए एक अच्छा क्षेत्र है, यहां के कर्मचारी और अधिक कुशल और संतुलित हो जाते हैं। वे कंपनी के लक्ष्य को पूरा करेंगे।',
              VastuStrings.marketingDepartment11: 'WSW क्षेत्र में विपणन विभाग संतोषजनक है। यहां के कर्मचारी आपके लक्ष्य प्राप्त करने में मदद करते हैं और इससे पैसे कमाते हैं।',
              VastuStrings.marketingDepartment12: 'पश्चिम क्षेत्र में विपणन विभाग के लिए अच्छा है। यहां के कर्मचारी कंपनी के लिए कड़ी मेहनत करते हैं और कभी भी लक्ष्यों को पीछे नहीं छोड़ते। वे कंपनी के साथ धोखा नहीं देते हैं।',
              VastuStrings.marketingDepartment13: 'WNW विपणन विभाग के लिए बहुत उपयुक्त नहीं है, कर्मचारी कभी भी यहां स्थिर नहीं होते हैं वे संवेदनशील और दुखी हो जाते हैं।',
              VastuStrings.marketingDepartment14: 'पश्चिमोत्तर क्षेत्र फ़ील्ड काम करने वाले कर्मचारियों के लिए अच्छा है। विपणन उनका शौक बन जाएगा। वे आसानी से अपने लक्ष्य तक पहुँच जाएंगे। और अपने काम से संतुष्ट हो जाएंगे।',
              VastuStrings.marketingDepartment15: 'NNW में विपणन विभाग अच्छा है। वे अपने ग्राहकों पर प्रभाव छोड़ेंगे। ग्राहक उनके उत्पादों को पसंद करेंगे।',
              VastuStrings.marketingDepartment16: 'उत्तर में विपणन अच्छा है। वे अपने उत्पाद के लिए लोगों को आसानी से प्रभावित कर सकते हैं और कंपनी के लिए अच्छी बिक्री प्राप्त कर सकते हैं।',
              VastuStrings.entranceMainDoor1 : 'प्रतिद्वंद्वियों से समस्याएँ।',
              VastuStrings.entranceMainDoor2 : 'बुरी नजर और ईर्ष्या से हानि।',
              VastuStrings.entranceMainDoor3 : 'धन, समृद्धि और अद्भुत वृद्धि की प्राचुर्य।',
              VastuStrings.entranceMainDoor4 : 'विरासती संपत्ति, धन और समृद्धि की प्राचुर्य की गारंटी।',
              VastuStrings.entranceMainDoor5 : 'धार्मिक मन और प्रतिस्पर्धा छोड़ें।',
              VastuStrings.entranceMainDoor6 : 'अजीब स्वभाव।',
              VastuStrings.entranceMainDoor7 : 'यहां रहने वाली लड़कियां परिवार के पारंपरिक धारणाओं का उल्लंघन करती हैं।',
              VastuStrings.entranceMainDoor8 : 'उच्च बैंक शेष।',
              VastuStrings.entranceMainDoor9 : 'आग से संबंधित दुर्घटनाएँ।',
              VastuStrings.entranceMainDoor10 : 'व्यय और अधिक लड़कियाँ।',
              VastuStrings.entranceMainDoor11 : 'धन, समृद्धि और सफलता।',
              VastuStrings.entranceMainDoor12 : 'सरकार और उच्च समाज से जुड़ाव।',
              VastuStrings.entranceMainDoor13 : 'तीव्र क्रोध।',
              VastuStrings.entranceMainDoor14 : 'अविश्वसनीय लोग।',
              VastuStrings.entranceMainDoor15 : 'निवासियों के दूसरों की समस्याओं के प्रति अभावशील और क्रूर।',
              VastuStrings.entranceMainDoor16 : 'हानियां, दुर्घटनाएँ, बीमारी और चोरी।',
              VastuStrings.entranceMainDoor17 : 'पुरुष बच्चा नकारात्मक होता है।',
              VastuStrings.entranceMainDoor18 : 'MNC कर्मचारियों के लिए अच्छा।',
              VastuStrings.entranceMainDoor19 : 'अत्यधिक समृद्धि और सफलता।',
              VastuStrings.entranceMainDoor20 : 'समृद्धि और प्रसिद्धि लाता है।',
              VastuStrings.entranceMainDoor21 : 'ऋण और वित्तीय हानि।',
              VastuStrings.entranceMainDoor22 : 'गरीबी, वित्तीय हानि और अपमान।',
              VastuStrings.entranceMainDoor23 : 'जीवन के हर पहलू में प्रयासों का अपव्यय।',
              VastuStrings.entranceMainDoor24 : 'धन, शक्ति और ताकत की हानि और बच्चों से दुख लाता है।',
              VastuStrings.entranceMainDoor25 : 'गरीबी और जीवन की अवधि को कम करता है।',
              VastuStrings.entranceMainDoor26 : 'करियर और संबंधों में अस्थिरता।',
              VastuStrings.entranceMainDoor27 : 'अविश्वसनीय धन, वृद्धि और समृद्धि।',
              VastuStrings.entranceMainDoor28 : 'सहज और खुशहाल जीवन।',
              VastuStrings.entranceMainDoor29 : 'काम में पूर्णतावादी।',
              VastuStrings.entranceMainDoor30 : 'मानसिक अवसाद के लिए प्रवृत्ति।',
              VastuStrings.entranceMainDoor31 : 'स्वास्थ्य और धन की समस्याएँ, ड्रग्स और शराब में आदत।',
              VastuStrings.entranceMainDoor32 : 'अपने लाभ के लिए अनुचित, अवैध तरीके से उपयोग करें।',
              VastuStrings.drinkingWater1  : 'अगर आप अपने पीने के पानी को उत्तर-पूर्व दिशा में रखते हैं तो पीने का पानी आपके शरीर को ठीक करता है।',
              VastuStrings.drinkingWater2  : 'यदि आप पीने का पानी उत्तर-पूर्व दिशा में रखते हैं, तो यह आपके दिमाग को साफ करता है, और आपकी ध्यान शक्ति को बढ़ाता है जिससे आपको भविष्यवाणी की दृष्टि मिलती है।',
              VastuStrings.drinkingWater3  : 'आप हमेशा खुशी महसूस करते हैं अगर आप पूर्व-उत्तर-पूर्व दिशा से पानी पीते हैं तो आपका जीवन अधिक खुशीपूर्ण हो जाता है।',
              VastuStrings.drinkingWater4  : 'पूर्व जोड़ने की दिशा, जोड़ने की दिशा है, अगर आपके अतिथि पूर्व दिशा में पानी पीते हैं तो वे आपके साथ अधिक सहज महसूस करेंगे और आपका बंधन उनके साथ मजबूत होगा।',
              VastuStrings.drinkingWater5  : 'ईएसई दिशा केवल वे लोगों के लिए अच्छा है जो गहरे विश्लेषण के रूप में काम करते हैं, अन्यथा यह आपको गलतफहमी में डाल देगा।',
              VastuStrings.drinkingWater6  : 'एसई दिशा आग का क्षेत्र है यहां पानी अनुचित है अन्यथा गुस्सा आपकी पहचान बन जाता है।',
              VastuStrings.drinkingWater7  : 'एसएसई आग का क्षेत्र है यहां पानी अनुचित है अन्यथा आप महसूस करेंगे कि आप अशक्त हैं और आपका आत्मविश्वास गायब हो जाएगा।',
              VastuStrings.drinkingWater8  : 'दक्षिण में पानी पीने के लिए अच्छा स्थान नहीं है, अगर आपके पीने का पानी वहां रखा जाएगा तो आपको कुछ स्वास्थ्य समस्या महसूस होगी।',
              VastuStrings.drinkingWater9  : 'पानी हमारे पैसे और भावनाओं है अगर आप अपने पीने के पानी को वहां रखते हैं तो आप दोनों को खो देंगे क्योंकि दक्षिण-पश्चिम एक बर्बादी का क्षेत्र है।',
              VastuStrings.drinkingWater10  : 'पानी को दक्षिण-पश्चिम दिशा में नहीं रखना चाहिए, आपके संबंध कमजोर हो जाते हैं और आपका वित्तीय नियंत्रण हार जाता है।',
              VastuStrings.drinkingWater11  : 'पानी को दक्षिण-पश्चिम-पश्चिम दिशा में रखना अच्छा स्थान नहीं है, बच्चे अशिक्षित हो जाते हैं और आप अपनी बचत खो देंगे।',
              VastuStrings.drinkingWater12  : 'पश्चिम क्षेत्र, आपको पीने के पानी को यहां रखने पर सामान्य परिणाम देता है, कोई समस्याएं नहीं होती हैं।',
              VastuStrings.drinkingWater13  : 'पानी को पश्चिम-उत्तर-पश्चिम दिशा में रखना अच्छा स्थान नहीं है, यह आपको मद्याह्नक की आदतें देता है।',
              VastuStrings.drinkingWater14  : 'आप अपने दोस्तों से सहारा प्राप्त करने के लिए उत्तर-पश्चिम दिशा में अपने पीने के पानी को रख सकते हैं।',
              VastuStrings.drinkingWater15  : 'उत्तर-पश्चिम-उत्तर-पश्चिम दिशा में पानी पीने के लिए एक अच्छा स्थान है, यह पति और पत्नी के संबंध को और भी सुगम बनाता है।',
              VastuStrings.drinkingWater16  : 'उत्तर दिशा में पानी पीने से सबसे अच्छे परिणाम मिलते हैं, यह आपको अपने जीवन के लक्ष्यों तक पहुँचने में मदद करेगा।',
              VastuStrings.purchaseDepartment1 : 'यदि आपका खरीदारी आपके इलाज और स्वास्थ्य के बारे में है। तो उत्तर-पूर्व खरीदारी विभाग के लिए सर्वश्रेष्ठ क्षेत्र है',
              VastuStrings.purchaseDepartment2 : 'पूर्व-उत्तर खरीदारी विभाग के लिए अच्छा क्षेत्र नहीं है। यहां के स्टाफ सुस्त और थक जाते हैं।',
              VastuStrings.purchaseDepartment3 : 'पूर्व-उत्तर खरीदारी विभाग में अच्छा होता है। यहां के स्टाफ आनंदमय होते हैं और अच्छे निर्णय लेते हैं। केवल एक शर्त नहीं करें कि इस क्षेत्र में विपरीत लिंग के लोगों को न रखें',
              VastuStrings.purchaseDepartment4 : 'पूर्व में खरीदारी विभाग आपको उच्च समाज के लोगों के साथ कनेक्शन बनाने में मदद करता है और आपको अच्छे ग्राहक मिलते हैं',
              VastuStrings.purchaseDepartment5 : 'पूर्व-दक्षिण-पूर्व में खरीदारी विभाग पसंद नहीं किया जाता है। क्योंकि लोग यहां विचलित हो जाते हैं और गलत निर्णय करते हैं',
              VastuStrings.purchaseDepartment6 : 'खरीदारी विभाग के लिए दक्षिण-पूर्व क्षेत्र अच्छा है। यहां केवल एक शर्त है कि कभी-कभी लोग या स्टाफ आक्रामक हो जाते हैं जो गलत निर्णयों का कारण बनता है।',
              VastuStrings.purchaseDepartment7 : 'दक्षिण-दक्षिण-पूर्व क्षेत्र सक्रिय और ऊर्जावान लोगों को प्राप्त करने में मदद करता है। यहां लोग गति में काम करते हैं और अच्छे निर्णय लेते हैं',
              VastuStrings.purchaseDepartment8 : 'अगर दक्षिण में खरीदारी विभाग है, तो आपको बिना थके बिना काम करने में मदद मिलती है। इसलिए यहां के स्टाफ लंबे समय तक काम करते हैं और आराम महसूस करते हैं जिससे अधिक काम छोटे समय में हो जाता है',
              VastuStrings.purchaseDepartment9 : 'SSW एक बर्बादी का क्षेत्र है, यदि आप यहां कोई निर्णय लेते हैं तो यह आपको हानि में ले जाएगा',
              VastuStrings.purchaseDepartment10 : 'पश्चिम-दक्षिण-पश्चिम एक संबंधों और कौशल का क्षेत्र है अगर खरीदारी विभाग यहां काम करेगा, तो स्टाफ अधिक कुशल हो जाएगा और उनके संबंध ग्राहकों के साथ अधिक स्मूद होंगे',
              VastuStrings.purchaseDepartment11 : 'पुर्चेज विभाग डब्ल्यूएसडब्ल्यू के लिए पसंदीदा है। यहां के खरीदारी आपकी बचत को बढ़ावा देगी',
              VastuStrings.purchaseDepartment12 : 'पुर्चेज विभाग पश्चिम के लिए पसंदीदा है। यहां के खरीदारी आपके लाभ को बढ़ाएगी',
              VastuStrings.purchaseDepartment13 : 'पुर्चेज विभाग WNW के लिए अधिकतम पसंदीदा नहीं है। क्योंकि आप यहां निर्णय लेते हैं तो यह आपको अवसाद में ले जाएगा',
              VastuStrings.purchaseDepartment14 : 'उत्तर-पश्चिम में खरीदारी विभाग आपको ग्राहकों का समर्थन प्राप्त करेगा',
              VastuStrings.purchaseDepartment15 : 'NNW खरीदारी विभाग के लिए एक अच्छा क्षेत्र है। लेकिन विपरीत लिंग यहां काम नहीं कर सकता अन्यथा वे ध्यान भटका देंगे',
              VastuStrings.purchaseDepartment16 : 'उत्तर में खरीदारी विभाग आपको सर्वश्रेष्ठ परिणाम देता है क्योंकि यहां के लोग अपने भविष्य के लिए अच्छे निर्णय लेते हैं और अच्छी खरीदारी करते हैं',
              VastuStrings.rndDepartment1 : 'यदि आप स्वास्थ्य या चिकित्सा पर काम कर रहे हैं, तो यह आरएनडी के लिए आदर्श क्षेत्र है',
              VastuStrings.rndDepartment2 : 'उत्तर-पूर्व क्षेत्र आरएनडी के लिए अच्छा नहीं है। आप अपनी चिंता तक पहुंच जाएंगे और अच्छे निर्णय नहीं ले सकते',
              VastuStrings.rndDepartment3 : 'ईएनई आरएनडी के लिए अच्छा है। यहां एक शर्त है कि आप विपरीत लिंग के साथ नहीं बैठ सकते। अन्यथा, उत्पादन कम होगा',
              VastuStrings.rndDepartment4 : 'पूर्व आरएनडी के लिए अच्छा है, यह आपके उत्पाद को अधिक प्रीमियम बनाएगा। और आपको प्रीमियम ग्राहकों तक पहुंचाने में मदद करेगा',
              VastuStrings.rndDepartment5 : 'ईएसई आरएनडी के लिए आदर्श क्षेत्र है। यहां आपको गहरा विश्लेषण करने में मदद मिलेगी और आपका उत्पाद अधिक विश्वसनीय और अधिक कुशल बनाएगा',
              VastuStrings.rndDepartment6 : 'एसई आरएनडी के लिए अच्छा क्षेत्र नहीं है। आक्रामकता गलत निर्णय लेगी, जो निकृष्टता लाएगा',
              VastuStrings.rndDepartment7 : 'एसएसई आरएनडी के लिए एक अच्छा क्षेत्र है। यदि आप मानव शक्ति और ताकत पर शोध करते हैं',
              VastuStrings.rndDepartment8 : 'अगर दक्षिणी क्षेत्र में आरएनडी है, तो यहां आप अपने उत्पाद पर आराम से अनुसंधान कर सकते हैं और एक अच्छा उत्पाद ला सकते हैं',
              VastuStrings.rndDepartment9 : 'एसएसडब्ल्यू एक आरएनडी का कचरा बन जाता है। इसकी एक्सेसबिलिटी की प्रकृति आपके अनुसंधान को फेंकती है',
              VastuStrings.rndDepartment10 : 'एसडब्ल्यू क्षेत्र एक अच्छी जगह है आरएनडी के लिए। क्योंकि यह जो काम करता है, उसे अधिक कौशल लाता है',
              VastuStrings.rndDepartment11 : 'डब्ल्यूएसडब्ल्यू आरएनडी के लिए एक अनुमति योन है। क्योंकि यहां बनने वाला उत्पाद आपके बचत को बढ़ाएगा',
              VastuStrings.rndDepartment12 : 'यदि आपका आरएनडी पश्चिम क्षेत्र में है, तो आपका उत्पाद एक अच्छा उत्पाद बनाएगा और यह उत्पाद आपके लाभों को बढ़ाएगा',
              VastuStrings.rndDepartment13 : 'डब्ल्यूएनडब्ल्यू आरएनडी के लिए एक अच्छा क्षेत्र नहीं है। इसकी एक्सेसबिलिटी की प्रकृति, आपके अनुसंधान को नष्ट करेगी और एक विफल उत्पाद बनाएगी',
              VastuStrings.rndDepartment14 : 'एनडब्ल्यू उत्पादक के लिए अच्छा क्षेत्र है। यहां बनने वाला उत्पाद आपकी मदद करेगा और आपके ग्राहकों से समर्थन प्राप्त करेगा',
              VastuStrings.rndDepartment15 : 'एनएनडब्ल्यू क्षेत्र आपके उत्पाद को लोगों के आकर्षण का देता है और आपको लोकप्रिय बनाता है',
              VastuStrings.rndDepartment16 : 'उत्तर के लिए आरएनडी अच्छा है, आप फायदे और हानियों की गणना कर सकते हैं और इस पर काम कर सकते हैं',
              VastuStrings.officeReception1 : 'यदि रिसेप्शन एनएए में है तो आपको स्वास्थ्य के क्षेत्र में काम करना चाहिए। यह आपको अच्छे परिणाम देगा।',
              VastuStrings.officeReception2 : 'एनई क्षेत्र रिसेप्शनिस्ट सुस्त और चिड़चिड़ा हो जाता है। यह ग्राहकों को दुःख देगा।',
              VastuStrings.officeReception3 : 'एनी में रिसेप्शनिस्ट ग्राहकों को खुशी देता है और उन्हें फिर से आने के लिए मजबूर करता है।',
              VastuStrings.officeReception4 : 'पूर्व में रिसेप्शनिस्ट आपको उच्च समाज के ग्राहक प्राप्त करने में मदद करता है और सरकारी अधिकारियों से जुड़ा रहता है।',
              VastuStrings.officeReception5 : 'पूर्व में रिसेप्शनिस्ट हमेशा भ्रमित रहेगा और उसका भ्रमित करने से ग्राहक परेशान हो जाएगा।',
              VastuStrings.officeReception6 : 'दक्षिण पूर्व में रिसेप्शनिस्ट अपनी शैली पर काम करता है, जो ग्राहकों को आकर्षित करती है और उन्हें अधिक बार लाता है।',
              VastuStrings.officeReception7 : 'दक्षिण दक्षिण पूर्व में, उसकी बातों में आत्मविश्वास है, जो आपके ग्राहकों में विश्वास को परिचालित करता है।',
              VastuStrings.officeReception8 : 'दक्षिण दिशा में रिसेप्शनिस्ट का एक बहुत ही आरामदायक और शांत मन होता है जो ग्राहकों को आराम देता है।',
              VastuStrings.officeReception9 : 'दक्षिण पश्चिम में रिसेप्शनिस्ट अपने काम से संतुष्ट नहीं होगा और जल्द ही छोड़ देगा।',
              VastuStrings.officeReception10 : 'पश्चिम में रिसेप्शनिस्ट को कुशल बनाता है जो अधिक ग्राहकों को लाता है।',
              VastuStrings.officeReception11 : 'पश्चिम-दक्षिण-पश्चिम में रिसेप्शनिस्ट को शिक्षित बनाता है, उसकी परामर्शन क्षमता अधिक ग्राहकों को लाता है।',
              VastuStrings.officeReception12 : 'पश्चिम में रिसेप्शनिस्ट को कड़ी मेहनत करने वाला बनाता है, वह कभी आपकी कंपनी छोड़ेगा नहीं और दीर्घकालिक होगा।',
              VastuStrings.officeReception13 : 'पश्चिम-उत्तर-पश्चिम दुःख का दिशा है जो रिसेप्शनिस्ट को अवसाद में डाल देगा।',
              VastuStrings.officeReception14 : 'उत्तर पश्चिम एक सहारे की दिशा है, इसलिए यहां के रिसेप्शनिस्ट हमेशा बेहतर सेवा देंगे।',
              VastuStrings.officeReception15 : 'उत्तर-उत्तर-पश्चिम आकर्षण की दिशा के अधीन है, इसलिए विपरीत लिंग रिसेप्शनिस्ट को आकर्षित करेगा और इसी प्रकार ग्राहकों को।',
              VastuStrings.officeReception16 : 'उत्तर अधिकारी अपनी मिठी आवाज से ग्राहकों को प्रभावित करेगी।',
              VastuStrings.waitingRoom1: 'ग्राहकों को चिकित्सा किया जाता है अगर वे उत्तर-पूर्व दिशा में प्रतीक्षा करते हैं, इसलिए यदि आप एक डॉक्टर हैं तो आपको उत्तर-पूर्व में प्रतीक्षा कक्ष डिज़ाइन करना चाहिए',
              VastuStrings.waitingRoom2: 'प्रतीक्षा कक्ष के लिए पूर्व-पूर्वेत्य ध्यानार्थ रोज़गार है, ग्राहक शांत और आराम करेंगे',
              VastuStrings.waitingRoom3: 'खुशी की दिशा में प्रतीक्षा ग्राहकों को छोटी-छोटी बातों से आनंद मिलेगा',
              VastuStrings.waitingRoom4: 'पूर्व एक सिर का क्षेत्र है अगर ग्राहक 15 मिनट से अधिक समय बिताए तो उसे लगेगा कि वह आपका सिर है',
              VastuStrings.waitingRoom5: 'पूर्व-दक्षिण-पूर्व एक चक्रवाती क्षेत्र है। प्रतीक्षा करने से ग्राहकों को भ्रमित किया जाता है, और भ्रम क्रोध में बदल जाता है',
              VastuStrings.waitingRoom6: 'दक्षिण-पूर्व एक अग्नि क्षेत्र है जो ग्राहकों को क्रोध दिखाता है',
              VastuStrings.waitingRoom7: 'प्रतीक्षा कक्ष एसएसई में ग्राहक आप पर शक्तिशाली बना देगा, जो असंतुष्ट कस्टमर्स के परिणाम होंगे',
              VastuStrings.waitingRoom8: 'दक्षिण दिशा में प्रतीक्षा कक्ष ग्राहकों को शांत और आरामदायक बनाता है, ग्राहक संतुष्ट और वफादार हो जाते हैं',
              VastuStrings.waitingRoom9: 'दक्षिण-पश्चिम छोड़ने की धर्मीक धरा, यदि ग्राहक डिप्रेशन के साथ वहाँ इंतजार करते हैं, तो उनका डिप्रेशन जल्दी ही खत्म हो जाएगा',
              VastuStrings.waitingRoom10: 'पश्चिम एक संबंध का क्षेत्र है, जो आपको ग्राहकों के साथ बेहतर संबंध प्राप्त करने में मदद करता है',
              VastuStrings.waitingRoom11: 'पश्चिम-दक्षिण-पश्चिम में प्रतीक्षा कक्ष ग्राहकों को उनकी समस्याओं के बारे में शिक्षित करेगा',
              VastuStrings.waitingRoom12: 'पश्चिम दिशा में प्रतीक्षा कक्ष आपको वफादार ग्राहक प्राप्त करने में मदद करेगा',
              VastuStrings.waitingRoom13: 'पश्चिम-उत्तर-पश्चिम में प्रतीक्षा कक्ष ग्राहकों को उनकी समस्याओं से छुटकारा प्राप्त करने में मदद करेगा',
              VastuStrings.waitingRoom14: 'उत्तर-पश्चिम दिशा में प्रतीक्षा कक्ष आपको ग्राहकों से समर्थन प्राप्त करेगा',
              VastuStrings.waitingRoom15: 'उत्तर-उत्तर-पश्चिम आकर्षण की दिशा है, इस क्षेत्र में प्रतीक्षा कक्ष अधिक ग्राहकों को आपकी ओर आकर्षित करेगा',
              VastuStrings.waitingRoom16: 'उत्तर दिशा में प्रतीक्षा कक्ष ग्राहकों को शांत रखने में मदद करेगा',
              VastuStrings.washroomOffice1: 'नॉर्थ-नॉर्थ ईशान में शौचालय आपके स्वास्थ्य पर बड़ा प्रभाव डालेगा। आपको अक्सर फ्लू होगा।',
              VastuStrings.washroomOffice2: 'अगर शौचालय पूर्व-उत्तर में है तो आप अपने ध्यान और दृष्टिकोण खो देंगे।',
              VastuStrings.washroomOffice3: 'यदि शौचालय पूर्व-पूर्व उत्तर में है तो आप अपने जीवन की खुशी खो देंगे।',
              VastuStrings.washroomOffice4: 'पूर्व आपको जनता से जोड़ता है और आपको टिकाऊ बनाता है, शौचालय बड़ा नकारात्मक प्रभाव डालेगा।',
              VastuStrings.washroomOffice5: 'पूर्व-दक्षिण पूर्ण शौचालय क्षेत्र है, यह आपको अनचाहे चूर्ण से मुक्ति प्रदान करेगा।',
              VastuStrings.washroomOffice6: 'दक्षिण पूर्व शौचालय आपकी धन वित्तीय बहाव को ब्लॉक करेगा। आपको कानूनी मुद्रा से पीड़ा होगी।',
              VastuStrings.washroomOffice7: 'यदि शौचालय दक्षिण-दक्षिण-पूर्व दिशा में है तो आप अपनी शक्ति और आत्मविश्वास खो देंगे।',
              VastuStrings.washroomOffice8: 'अपमान आपकी पहचान बन जाता है अगर शौचालय दक्षिण दिशा में है।',
              VastuStrings.washroomOffice9: 'दक्षिण-दक्षिण पश्चिम शौचालय क्षेत्र आपके जीवन से समस्याओं को हटाने में मदद करता है।',
              VastuStrings.washroomOffice10: 'आपके रिश्ते कमजोर हो जाएंगे और आपके कौशल बेकार होंगे अगर शौचालय दक्षिण पश्चिम में है।',
              VastuStrings.washroomOffice11: 'यदि शौचालय पश्चिम-दक्षिण पश्चिम दिशा में है तो आप शिक्षा और बचत से पीड़ित होंगे।',
              VastuStrings.washroomOffice12: 'यदि शौचालय पश्चिम दिशा में है तो हानियाँ आपकी पहचान बन जाएंगी।',
              VastuStrings.washroomOffice13: 'पश्चिम उत्तर पश्चिम शौचालय के लिए सर्वश्रेष्ठ माना जाता है, यह आपको अपने अवसाद को हटाने में मदद करता है।',
              VastuStrings.washroomOffice14: 'उत्तर-पश्चिम में शौचालय आपको दोस्तों और परिवार से सहारा पाने के लिए पीड़ित करेगा।',
              VastuStrings.washroomOffice15: 'पति और पत्नी कभी एक दूसरे के बीच प्रेम महसूस नहीं करेंगे और किसी और से प्यार का अनुभव करेंगे।',
              VastuStrings.washroomOffice16: 'उत्तर धरती क्षेत्र में शौचालय आपकी आय को ब्लॉक करेगा और आप अपने ग्राहकों को खो दोगे।',
              VastuStrings.dustbinOffice1: 'NNE में डस्टबिन से आपको मौसमिक रूप से संक्रामित व्यक्ति बना देगा।',
              VastuStrings.dustbinOffice2: 'अगर डस्टबिन उत्तर-पूर्व में है तो आप अपने काम पर ध्यान केंद्रित नहीं कर सकते।',
              VastuStrings.dustbinOffice3: 'ENE दिशा में डस्टबिन होने से जीवन में खुशी की कमी होगी।',
              VastuStrings.dustbinOffice4: 'अगर डस्टबिन पूर्व में है तो लोग आपकी पहचान के बारे में अनावश्यक बातें करेंगे।',
              VastuStrings.dustbinOffice5: 'ESE एक अच्छा क्षेत्र है डस्टबिन के लिए, यह आपको ध्यान केंद्रित रहने में मदद करेगा।',
              VastuStrings.dustbinOffice6: 'SE में डस्टबिन आपको नकदी और स्टॉक प्रबंधन में पीड़ा देगा।',
              VastuStrings.dustbinOffice7: 'SSE दिशा में डस्टबिन होने से आपकी आत्मविश्वास कमजोर हो जाएगा।',
              VastuStrings.dustbinOffice8: 'अगर डस्टबिन दक्षिण में है तो आप प्रसिद्धि की इच्छा का शिकार होंगे, लेकिन लोग आपको कभी प्रसिद्ध नहीं करेंगे।',
              VastuStrings.dustbinOffice9: 'SSW डस्टबिन के लिए आदर्श क्षेत्र है, यह आपकी जिंदगी से अनचाहे व्यक्तियों को हटाने में मदद करेगा।',
              VastuStrings.dustbinOffice10: 'अगर डस्टबिन पश्चिम में है तो आप अपने रिश्तों में स्थिरता नहीं पाएंगे।',
              VastuStrings.dustbinOffice11: 'WSW क्षेत्र में डस्टबिन होने से बच्चे अपनी शिक्षा का डर महसूस करेंगे।',
              VastuStrings.dustbinOffice12: 'पश्चिम दिशा में डस्टबिन होने से आपके लाभ छोटे हो जाएंगे।',
              VastuStrings.dustbinOffice13: 'WNW सबसे अच्छा संभावित स्थान है डस्टबिन के लिए।',
              VastuStrings.dustbinOffice14: 'अगर डस्टबिन उत्तर-पश्चिम में है तो दोस्तों और परिवार से सहारा मिलने में कठिनाई होगी।',
              VastuStrings.dustbinOffice15: 'NNW दिशा में डस्टबिन होने से पति-पत्नी एक-दूसरे के बीच प्यार का एहसास नहीं करेंगे और किसी और से प्यार करेंगे।',
              VastuStrings.dustbinOffice16: 'उत्तर दिशा में डस्टबिन होने से आपको ग्राहकों और धन से पीड़ा होगी।',
              VastuStrings.weightMachine1: 'NNE मोटाई मशीन के लिए अच्छा नहीं है यह आपको स्वास्थ्य समस्याओं को दे गा',
              VastuStrings.weightMachine2: 'अगर मोटाई मशीन ने उत्तर पूर्व में रख दी है तो आप अपने काम पर ध्यान नहीं दे पाएंगे',
              VastuStrings.weightMachine3: 'यदि मोटाई मशीन ईएनई में है तो जीवन की आनंददायकता खो जाएगी',
              VastuStrings.weightMachine4: 'अगर आपकी मोटाई मशीन पूर्व में है तो यह आपको उच्च ग्राहकों के पास ले जाएगा',
              VastuStrings.weightMachine5: 'मोटाई मशीन के लिए ईएसई सबसे आदर्श क्षेत्र है, यह आपको अनावश्यक तनाव से राहत देगा',
              VastuStrings.weightMachine6: 'अगर मोटाई मशीन दक्षिण पूर्व में है तो आपका नकदी निकासी बंद हो जाएगा',
              VastuStrings.weightMachine7: 'यदि मोटाई मशीन ईएसएसई दिशा में है तो आप शक्ति और आत्मविश्वास खो देंगे',
              VastuStrings.weightMachine8: 'दक्षिण दिशा में मोटाई मशीन होने पर आपका नाम प्रसिद्धी कम हो जाएगा',
