              AppStrings.whoIsArchitect: 'వాస్తు ఆర్కిటెక్ట్ ఎవరు?',
              AppStrings.whoIsArchitectAns: 'వాస్తు ఆర్కిటెక్ట్ అనేది ఒక నిపుణుడు, అతను వాస్తు శాస్త్రం యొక్క సూత్రాల ప్రకారం భవనాలను డిజైన్ చేస్తాడు. వాస్తు శాస్త్రం అనేది ఒక పురాతన భారతీయ విజ్ఞానం, ఇది మానవ నిర్మిత వాతావరణాన్ని సహజ శక్తులతో సమన్వయం చేయడానికి పనిచేస్తుంది. ఈ ఆర్కిటెక్ట్లు దిశలు, లేఅవుట్ మరియు డిజైన్‌పై దృష్టి సారిస్తారు, తద్వారా ఐదు మూలకాల మధ్య (భూమి, నీరు, అగ్ని, గాలి, ఆకాశం) సమతుల్యతను స్థాపించి, ఆరోగ్యం, సంపద మరియు ఆనందాన్ని పెంపొందించవచ్చు.',
