              AppStrings.whoIsArchitectAns: 'বাস্তু আর্কিটেক্ট একজন বিশেষজ্ঞ, যিনি বাস্তু শাস্ত্রের নীতিগুলির উপর ভিত্তি করে ভবনগুলি ডিজাইন করেন। বাস্তু শাস্ত্র একটি প্রাচীন ভারতীয় বিজ্ঞান, যা মানব নির্মিত পরিবেশকে প্রাকৃতিক শক্তির সাথে সামঞ্জস্যে আনার কাজ করে। এই আর্কিটেক্টরা দিক, বিন্যাস এবং ডিজাইনের উপর মনোযোগ দেন যাতে পাঁচটি উপাদান (পৃথিবী, জল, আগুন, বায়ু, আকাশ) এর মধ্যে ভারসাম্য স্থাপন করা যায়, যা স্বাস্থ্য, সম্পদ এবং সুখ বৃদ্ধিতে সহায়ক হয়।',
