              AppStrings.whoIsArchitectAns: 'ವಾಸ್ತು ಶಿಲ್ಪಿ ಎಂದರೆ ವಾಸ್ತು ಶಾಸ್ತ್ರದ ತತ್ವಗಳ ಪ್ರಕಾರ ಕಟ್ಟಡಗಳನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸುವ ತಜ್ಞನು. ವಾಸ್ತು ಶಾಸ್ತ್ರವು ಮಾನವ ನಿರ್ಮಿತ ಪರಿಸರವನ್ನು ಪ್ರಕೃತಿಯ ಶಕ್ತಿಗಳೊಂದಿಗೆ ಹೊಂದಾಣಿಕೆಗೆ ತರುವ ಪ್ರಾಚೀನ ಭಾರತೀಯ ವಿಜ್ಞಾನವಾಗಿದೆ. ಈ ಶಿಲ್ಪಿಗಳು ದಿಕ್ಕುಗಳು, ವಿನ್ಯಾಸ ಹಾಗೂ ವಿನ್ಯಾಸದ ಮೇಲೆ ಗಮನಹರಿಸುತ್ತಾರೆ ಹೀಗಾಗಿ ಐದು ಅಂಶಗಳ (ಭೂಮಿ, ಜಲ, ಅಗ್ನಿ, ವಾಯು, ಆಕಾಶ) ನಡುವಿನ ಸಮತೋಲನವನ್ನು ಸ್ಥಾಪಿಸಲು, ಆರೋಗ್ಯ, ಆಸ್ತಿ ಮತ್ತು ಸಂತೋಷವನ್ನು ಉತ್ತೇಜಿಸುತ್ತವೆ.',
