              AppStrings.whoIsArchitectAns: 'വാസ്തു ആർക്കിടെക്ട് വാസ്തു ശാസ്ത്രത്തിന്റെ സിദ്ധാന്തങ്ങൾ അനുസരിച്ച് കെട്ടിടങ്ങൾ രൂപകൽപ്പന ചെയ്യുന്ന ഒരു വിദഗ്ധനാണ്. വാസ്തു ശാസ്ത്രം മനുഷ്യനിർമിതമായ അന്തരീക്ഷത്തെ പ്രകൃതിശേഷികളുമായുള്ള സാമ്യമിലേക്ക് കൊണ്ടുവരുന്ന ഒരു പുരാതന ഇന്ത്യൻ ശാസ്ത്രമാണ്. ഈ ആർക്കിടെക്ടുകൾ ദിശകൾ, ലേയൗട്ടുകൾ, രൂപകൽപ്പന എന്നിവയിലേക്ക് ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നു, അഞ്ച് ഘടകങ്ങൾ (ഭൂമി, ജലം, അഗ്നി, വായു, ആകാശം) തമ്മിലുള്ള സമത്വം സ്ഥാപിക്കാൻ, ആരോഗ്യം, ധനം, സന്തോഷം എന്നിവയ്ക്ക് പ്രോത്സാഹനം നൽകുന്നു.',
